import { Q, W, indexBy } from './_helper.js';

const M = (n, title, qs, opts) => W('H12TA', 'tieng-anh', n, title, qs, opts);

export const H12TA_WEEKS = [
  // ──────────────── HK1 ────────────────
  M(1, 'Unit 1 — Life Stories (Vocabulary + Past tenses)', [
    Q('"She ___ in Hanoi for ten years before she moved to Saigon."', ['had lived', 'was living', 'has lived (đã sống — sai vì lùi thì)', 'has lived'], 0, 'Quá khứ hoàn thành (had + V3) cho hành động xảy ra trước một mốc quá khứ khác (before she moved).', ['Đúng — had + V3 (had lived) diễn tả hành động xảy ra và kéo dài trước một mốc quá khứ khác (moved).', 'Sai — was living (quá khứ tiếp diễn) chỉ hành động đang diễn ra, không diễn tả sự hoàn tất trước "before she moved".', 'Sai — has lived là hiện tại hoàn thành, không lùi thì cho ngữ cảnh quá khứ (before she moved).', 'Sai — has lived dùng cho hiện tại, sai thì với mốc quá khứ "before she moved".']),
    Q('A person who has achieved great success and is admired is called a(n) ___.', ['celebrity (người nổi tiếng — gần nghĩa nhưng ít trang trọng hơn icon)', 'icon', 'figurehead', 'figure'], 1, 'Icon - người nổi tiếng được nhiều người ngưỡng mộ, có tầm ảnh hưởng văn hoá.', ['Sai — celebrity gần nghĩa nhưng ít trang trọng và không nhấn tầm ảnh hưởng văn hoá như icon.', 'Đúng — icon là người nổi tiếng được ngưỡng mộ, có tầm ảnh hưởng văn hoá lớn.', 'Sai — figurehead chỉ người đứng đầu trên danh nghĩa (bù nhìn), nhầm nghĩa.', 'Sai — figure quá chung chung, không diễn tả sự ngưỡng mộ và tầm ảnh hưởng.']),
    Q('"While I ___ dinner, the lights went out."', ['had cooked', 'have cooked', 'cooked', 'was cooking'], 3, 'Past continuous (was/were V-ing) cho hành động đang diễn ra thì bị một hành động khác chen vào.', ['Sai — had cooked (quá khứ hoàn thành) chỉ hành động hoàn tất trước, không phải hành động đang diễn ra bị chen ngang.', 'Sai — have cooked là hiện tại hoàn thành, sai thì với ngữ cảnh quá khứ (went out).', 'Sai — cooked (quá khứ đơn) không diễn tả hành động đang diễn ra thì bị cắt ngang.', 'Đúng — past continuous (was cooking) cho hành động đang diễn ra thì bị một hành động khác (went out) chen vào.']),
    Q('"Marie Curie was the first woman ___ the Nobel Prize."', ['who wins (HS nhầm dùng mệnh đề quan hệ)', 'who won (mệnh đề quan hệ thì quá khứ)', 'to win', 'winning'], 2, 'Cấu trúc the first/second/last + N + to V (nguyên thể chỉ mục đích/đặc điểm).', ['Sai — who wins dùng mệnh đề quan hệ và sai thì (hiện tại), không hợp cấu trúc the first + N + to V.', 'Sai — who won là mệnh đề quan hệ, không phải cấu trúc the first + N + to V.', 'Đúng — cấu trúc the first/second/last + N + to V (nguyên thể) chỉ đặc điểm.', 'Sai — winning (V-ing) không dùng sau the first + N; phải là to V.']),
    Q('"He ___ as a doctor since he graduated."', ['has been working', 'was working', 'has worked (present perfect đơn, không nhấn liên tục)', 'worked'], 0, 'Present perfect continuous (has been V-ing) cho hành động bắt đầu trong quá khứ và còn tiếp diễn.', ['Đúng — present perfect continuous (has been working) cho hành động bắt đầu trong quá khứ và còn tiếp diễn (since he graduated).', 'Sai — was working (quá khứ tiếp diễn) không khớp với "since", vốn cần hiện tại hoàn thành.', 'Sai — has worked đúng thì nhưng không nhấn tính liên tục, kém phù hợp với "since he graduated".', 'Sai — worked (quá khứ đơn) không kết hợp với "since" chỉ khoảng kéo dài đến hiện tại.']),
    Q('Synonym of "perseverance" is ___.', ['patience (kiên nhẫn — gần nghĩa nhưng khác sắc thái)', 'persistence', 'laziness', 'weakness'], 1, 'Perseverance = persistence: sự kiên trì, bền bỉ.', ['Sai — patience (kiên nhẫn) gần nghĩa nhưng khác sắc thái, không nhấn sự bền bỉ vượt khó.', 'Đúng — perseverance = persistence: sự kiên trì, bền bỉ.', 'Sai — laziness (lười biếng) là trái nghĩa.', 'Sai — weakness (điểm yếu) nhầm nghĩa, không liên quan đến kiên trì.']),
  ]),

  M(2, 'Unit 1 — Life Stories (Reported speech basics)', [
    Q('Direct: "I am happy", she said. → Reported: She said (that) ___.', ['she was happy', 'she has been happy', 'she is happy', 'she were happy'], 0, 'Khi đổi sang tường thuật, lùi 1 thì: am/is → was.', ['Đúng — khi tường thuật lùi 1 thì: am/is → was (she was happy).', 'Sai — has been happy lùi thì sai; present simple "am" phải thành "was", không phải present perfect.', 'Sai — is happy không lùi thì sau "she said".', 'Sai — were happy sai chia động từ với chủ ngữ số ít "she" (phải was).']),
    Q('"Where do you live?" he asked. → He asked me where ___.', ['did I live', 'I live', 'I lived', 'do I live'], 2, 'Câu hỏi tường thuật: dùng trật tự khẳng định + lùi thì (do you live → I lived).', ['Sai — did I live giữ trật tự nghi vấn và không lùi thì, sai trong câu tường thuật.', 'Sai — I live không lùi thì sau "asked" (phải lùi do you live → I lived).', 'Đúng — câu hỏi tường thuật dùng trật tự khẳng định + lùi thì (do you live → I lived).', 'Sai — do I live giữ trợ động từ nghi vấn, sai trong câu tường thuật.']),
    Q('"Don\'t open the window," she told him. → She told him ___ the window.', ['no opening', 'to not open', 'don\'t open', 'not to open'], 3, 'Mệnh lệnh phủ định tường thuật: told sb NOT TO V.', ['Sai — no opening sai cấu trúc; mệnh lệnh phủ định tường thuật dùng not to V.', 'Sai — to not open sai trật tự; phải đặt "not" trước "to" (not to open).', 'Sai — don\'t open giữ nguyên dạng mệnh lệnh trực tiếp, không phải tường thuật.', 'Đúng — mệnh lệnh phủ định tường thuật: told sb NOT TO V (not to open).']),
    Q('"Can you help me?" she asked. → She asked if I ___ help her.', ['could', 'would (HS nhầm lùi will sau asked)', 'will (không lùi thì sau asked)', 'can (giữ nguyên modal, không lùi thì)'], 0, 'Yes/no question tường thuật: dùng if/whether + lùi thì can → could.', ['Đúng — yes/no question tường thuật dùng if/whether + lùi thì can → could.', 'Sai — would là lùi của will, không phải của can; nhầm modal.', 'Sai — will không lùi thì sau "asked"; modal phải lùi.', 'Sai — can giữ nguyên modal, không lùi thì sau "asked".']),
    Q('Reported: "I will call you tomorrow." → He said he ___ call me ___.', ['will/tomorrow', 'would/the next day', 'would/tomorrow', 'will/the next day'], 1, 'Will → would; tomorrow → the next day/the following day.', ['Sai — will không lùi thì sau "said" và "tomorrow" phải đổi thành "the next day".', 'Đúng — will → would; tomorrow → the next day/the following day khi tường thuật.', 'Sai — would đúng nhưng "tomorrow" phải đổi thành "the next day" khi lùi mốc thời gian.', 'Sai — will không lùi thì; chỉ phần thời gian đúng.']),
    Q('"I have finished my homework," he said. → He said (that) he ___ his homework.', ['had finished', 'has finished', 'finished', 'finishes'], 0, 'Present perfect → past perfect khi tường thuật.', ['Đúng — present perfect → past perfect (had finished) khi tường thuật.', 'Sai — has finished không lùi thì sau "he said".', 'Sai — finished (quá khứ đơn) chưa lùi đủ; present perfect phải thành past perfect.', 'Sai — finishes (hiện tại đơn) không lùi thì, sai hoàn toàn.']),
  ]),

  M(3, 'Unit 2 — Urbanisation (Vocabulary + Present perfect)', [
    Q('"The population of this city ___ rapidly in the last decade."', ['grew (quá khứ đơn, sai vì có in the last decade)', 'grows (hiện tại đơn, không khớp khoảng thời gian)', 'has grown', 'is growing'], 2, '"In the last decade" - dấu hiệu present perfect (has/have V3).', ['Sai — grew (quá khứ đơn) không khớp với "in the last decade" vốn cần present perfect.', 'Sai — grows (hiện tại đơn) không diễn tả khoảng từ quá khứ đến hiện tại.', 'Đúng — "in the last decade" là dấu hiệu present perfect (has grown).', 'Sai — is growing (hiện tại tiếp diễn) chỉ việc đang xảy ra, không tổng kết cả thập kỉ.']),
    Q('"Urbanisation" refers to the process of ___.', ['reducing city populations', 'people moving from rural areas to cities', 'building rural areas', 'people moving from cities to rural areas'], 1, 'Urbanisation = đô thị hoá - dân chuyển từ nông thôn ra thành thị.', ['Sai — đô thị hoá không phải giảm dân số thành phố.', 'Đúng — urbanisation là dân chuyển từ nông thôn ra thành thị.', 'Sai — đô thị hoá không phải xây dựng vùng nông thôn.', 'Sai — đây là chiều ngược lại (thành thị về nông thôn), nhầm nghĩa.']),
    Q('A negative effect of urbanisation is ___.', ['overcrowding', 'better education', 'more jobs', 'modern facilities'], 0, 'Overcrowding (quá tải dân số) là hệ quả tiêu cực của đô thị hoá.', ['Đúng — overcrowding (quá tải dân số) là hệ quả tiêu cực của đô thị hoá.', 'Sai — better education là tác động tích cực, không phải tiêu cực.', 'Sai — more jobs là lợi ích, không phải hệ quả tiêu cực.', 'Sai — modern facilities là mặt tích cực của đô thị hoá.']),
    Q('"How long ___ you ___ in this neighbourhood?"', ['do/live', 'have/lived', 'did/live', 'are/living'], 1, 'Câu hỏi với "how long" + present perfect (have you lived).', ['Sai — do/live (hiện tại đơn) không dùng với "how long" chỉ khoảng kéo dài đến hiện tại.', 'Đúng — "how long" + present perfect (have you lived).', 'Sai — did/live (quá khứ) không khớp với khoảng kéo dài đến hiện tại.', 'Sai — are/living (hiện tại tiếp diễn) không dùng với "how long" cho khoảng kéo dài.']),
    Q('Synonym of "infrastructure" is ___.', ['public facilities', 'population', 'furniture', 'decoration'], 0, 'Infrastructure = các cơ sở vật chất công cộng (đường, điện, nước…).', ['Đúng — infrastructure = public facilities (đường, điện, nước…).', 'Sai — population (dân số) nhầm nghĩa, không phải cơ sở vật chất.', 'Sai — furniture (nội thất) nhầm nghĩa.', 'Sai — decoration (trang trí) nhầm nghĩa.']),
    Q('"The government has ___ new policies to ease traffic congestion."', ['to introduce', 'introduce', 'introducing', 'introduced'], 3, 'Has + V3 (introduced) - present perfect.', ['Sai — to introduce sai dạng sau "has"; cần V3.', 'Sai — introduce (nguyên thể) không hợp với "has"; cần V3.', 'Sai — introducing (V-ing) không tạo thành present perfect; cần V3.', 'Đúng — has + V3 (introduced) là present perfect.']),
  ]),

  M(4, 'Unit 2 — Comparatives + Quantifiers', [
    Q('"The traffic in Hanoi is ___ than in my hometown."', ['worst (so sánh nhất, sai cấu trúc than)', 'badder', 'worse', 'more bad'], 2, 'So sánh hơn của "bad" là "worse" (bất quy tắc).', ['Sai — worst là so sánh nhất, không dùng với "than".', 'Sai — badder không tồn tại; "bad" là bất quy tắc.', 'Đúng — so sánh hơn của "bad" là "worse" (bất quy tắc).', 'Sai — more bad sai; "bad" không dùng more, mà là "worse".']),
    Q('"The more people move to the city, ___."', ['more crowded it becomes', 'the crowded more it becomes', 'the most crowded it becomes', 'the more crowded it becomes'], 3, 'Cấu trúc "The + comp ..., the + comp ...": càng ... càng ...', ['Sai — thiếu "the" đầu vế; cấu trúc phải là "the more...".', 'Sai — sai trật tự "the crowded more"; phải "the more crowded".', 'Sai — dùng so sánh nhất "the most"; cấu trúc này cần so sánh hơn.', 'Đúng — cấu trúc "The + comp..., the + comp...": càng... càng...']),
    Q('"There are ___ skyscrapers in Tokyo than in Hanoi."', ['more', 'most (so sánh nhất, sai vì có than)', 'much (dùng cho danh từ không đếm được)', 'many (số nhiều nhưng không phải so sánh hơn)'], 0, 'So sánh hơn của "many": more (skyscrapers - đếm được số nhiều).', ['Đúng — so sánh hơn của "many" là more (skyscrapers đếm được số nhiều).', 'Sai — most là so sánh nhất, không dùng với "than".', 'Sai — much dùng cho danh từ không đếm được; skyscrapers đếm được.', 'Sai — many không phải dạng so sánh hơn.']),
    Q('"___ pollution in big cities is harmful to health."', ['An (mạo từ trước nguyên âm, sai loại từ)', '∅ (no article)', 'A (mạo từ không xác định, sai loại từ)', 'The (mạo từ xác định, dùng khi cụ thể)'], 1, 'Pollution - danh từ trừu tượng không đếm được, nói chung không cần mạo từ.', ['Sai — "An" sai loại từ; pollution là danh từ không đếm được nói chung không cần mạo từ.', 'Đúng — pollution là danh từ trừu tượng không đếm được, nói chung không cần mạo từ.', 'Sai — "A" là mạo từ không xác định, không dùng cho danh từ không đếm được nói chung.', 'Sai — "The" chỉ dùng khi cụ thể; ở đây nói chung chung nên không cần.']),
    Q('"This is ___ city I have ever visited."', ['the modernest', 'the more modern', 'the most modern', 'more modern'], 2, '"Ever" - dấu hiệu so sánh nhất + present perfect.', ['Sai — modernest không tồn tại; "modern" so sánh nhất là "the most modern".', 'Sai — the more modern là so sánh hơn; "ever" cần so sánh nhất.', 'Đúng — "ever" là dấu hiệu so sánh nhất + present perfect (the most modern).', 'Sai — more modern là so sánh hơn, không hợp với "ever".']),
    Q('"There aren\'t ___ green spaces in this district."', ['a lot (cần a lot of trước danh từ)', 'much (dùng cho danh từ không đếm được)', 'many', 'few (chỉ ít, dùng trong câu khẳng định)'], 2, '"Green spaces" - đếm được số nhiều, dùng "many" trong câu phủ định.', ['Sai — "a lot" phải thành "a lot of" trước danh từ.', 'Sai — much dùng cho danh từ không đếm được; green spaces đếm được.', 'Đúng — green spaces đếm được số nhiều, dùng "many" trong câu phủ định.', 'Sai — few mang nghĩa "ít" và dùng trong câu khẳng định, không hợp ở đây.']),
  ]),

  M(5, 'Unit 3 — The Green Movement (Vocabulary + Passive)', [
    Q('"Trees ___ to absorb carbon dioxide."', ['are planted', 'were planting', 'planting', 'plant (chủ động hiện tại đơn, thiếu chủ thể)'], 0, 'Bị động hiện tại đơn: are/is + V3 (are planted).', ['Đúng — bị động hiện tại đơn: are/is + V3 (are planted).', 'Sai — were planting (quá khứ tiếp diễn chủ động) sai cả thì lẫn thể.', 'Sai — planting (V-ing) không tạo thành bị động.', 'Sai — plant (chủ động hiện tại đơn) thiếu chủ thể hành động, ngữ cảnh cần bị động.']),
    Q('"Renewable energy" is energy from sources that ___.', ['are polluting', 'will run out', 'cannot be replaced', 'can be replenished naturally'], 3, 'Renewable - tái tạo được, có thể bổ sung tự nhiên (mặt trời, gió…).', ['Sai — renewable không phải nguồn gây ô nhiễm.', 'Sai — renewable không phải nguồn sẽ cạn kiệt.', 'Sai — đây mô tả nguồn không tái tạo được (trái nghĩa).', 'Đúng — renewable là nguồn tái tạo, có thể bổ sung tự nhiên.']),
    Q('"A lot of waste ___ into the river by factories last year."', ['was dumped', 'is dumped', 'were dumped', 'dumped'], 0, '"Waste" - danh từ không đếm được → was + V3; "last year" → quá khứ.', ['Đúng — "waste" không đếm được → was + V3; "last year" → quá khứ (was dumped).', 'Sai — is dumped (hiện tại) không khớp "last year".', 'Sai — were dumped sai vì "waste" không đếm được (số ít → was).', 'Sai — dumped đứng một mình thiếu trợ động từ bị động (was).']),
    Q('Synonym of "to reduce" is ___.', ['double', 'expand', 'cut down on', 'increase'], 2, '"Cut down on" = giảm bớt, hạn chế (phrasal verb phổ biến).', ['Sai — double (gấp đôi) nhầm nghĩa, không phải giảm.', 'Sai — expand (mở rộng) là trái nghĩa.', 'Đúng — cut down on = giảm bớt, hạn chế.', 'Sai — increase (tăng) là trái nghĩa.']),
    Q('"Plastic bags should ___ to protect the environment."', ['to ban', 'be banning (modal + be V-ing, sai chủ động)', 'be banned', 'being banned'], 2, 'Modal + bị động: should + be + V3.', ['Sai — to ban sai dạng sau modal; phải be + V3.', 'Sai — be banning là chủ động tiếp diễn, ngữ cảnh cần bị động.', 'Đúng — modal + bị động: should + be + V3 (be banned).', 'Sai — being banned không dùng sau modal; phải be banned.']),
    Q('"Recycling" means ___.', ['throwing away rubbish', 'burying waste', 'converting waste into reusable materials', 'burning waste'], 2, 'Recycling - tái chế - biến rác thải thành nguyên liệu sử dụng lại.', ['Sai — vứt rác đi không phải tái chế.', 'Sai — chôn lấp rác không phải tái chế.', 'Đúng — recycling là biến rác thải thành nguyên liệu sử dụng lại.', 'Sai — đốt rác không phải tái chế.']),
  ]),

  M(6, 'Unit 3 — Passive in all tenses', [
    Q('"The report ___ by the time you arrive tomorrow."', ['is being finished', 'will have been finished', 'will be finished', 'will finish'], 1, '"By the time" + future → future perfect; bị động: will have been + V3.', ['Sai — is being finished (hiện tại tiếp diễn bị động) không khớp mốc tương lai "by the time you arrive tomorrow".', 'Đúng — "by the time" + tương lai → future perfect bị động: will have been + V3.', 'Sai — will be finished là tương lai đơn bị động, không nhấn sự hoàn tất trước mốc.', 'Sai — will finish là chủ động, ngữ cảnh cần bị động.']),
    Q('"This building ___ since 2010."', ['is used', 'has been used', 'was used (quá khứ đơn bị động, không khớp since)', 'has used'], 1, '"Since" - present perfect; bị động: has been + V3.', ['Sai — is used (hiện tại đơn bị động) không khớp "since".', 'Đúng — "since" → present perfect; bị động: has been + V3 (has been used).', 'Sai — was used (quá khứ đơn bị động) không khớp "since".', 'Sai — has used là chủ động, ngữ cảnh cần bị động.']),
    Q('"The trees ___ planted right now."', ['are be', 'are being', 'being (thiếu trợ động từ are)', 'are been'], 1, 'Present continuous passive: am/is/are + being + V3.', ['Sai — are be sai cấu trúc; bị động tiếp diễn là are being + V3.', 'Đúng — present continuous passive: am/is/are + being + V3 (are being planted).', 'Sai — being thiếu trợ động từ "are".', 'Sai — are been sai cấu trúc; phải là are being + V3.']),
    Q('"The proposal ___ when I came in."', ['was discussed', 'was being discussed', 'is discussed', 'had been discussed'], 1, 'Past continuous passive: was/were + being + V3 - mô tả việc đang diễn ra trong quá khứ.', ['Sai — was discussed (quá khứ đơn bị động) không diễn tả việc đang diễn ra khi "I came in".', 'Đúng — past continuous passive: was/were + being + V3, mô tả việc đang diễn ra trong quá khứ.', 'Sai — is discussed (hiện tại bị động) không khớp ngữ cảnh quá khứ.', 'Sai — had been discussed (quá khứ hoàn thành bị động) chỉ việc đã xong trước, không phải đang diễn ra.']),
    Q('"They say that he is a great leader." → He ___ to be a great leader.', ['says (chủ động hiện tại đơn, thiếu bị động)', 'is saying', 'is said', 'was said (bị động quá khứ, sai về thời)'], 2, 'Bị động câu "They say that S + V": S + is said + to V (hiện tại).', ['Sai — says là chủ động, ngữ cảnh cần bị động.', 'Sai — is saying là chủ động tiếp diễn, sai thể.', 'Đúng — bị động của "They say that S V": S + is said + to V.', 'Sai — was said sai về thời (gốc là "is a great leader" ở hiện tại).']),
    Q('"Carbon emissions need ___ urgently."', ['reducing', 'be reduced', 'to be reduced', 'to reduce'], 2, '"Need to V" - chủ ngữ chịu tác động → need to be V3 (bị động).', ['Sai — reducing (V-ing) mang nghĩa chủ động; chủ ngữ chịu tác động nên cần bị động.', 'Sai — be reduced thiếu "to" sau "need".', 'Đúng — "need to V" với chủ ngữ chịu tác động → need to be V3 (bị động).', 'Sai — to reduce là chủ động; chủ ngữ là đối tượng bị giảm nên cần bị động.']),
  ]),

  M(7, 'Unit 4 — The Mass Media (Vocabulary + Conditionals 1-2)', [
    Q('"If it ___ tomorrow, we will cancel the trip."', ['would rain', 'will rain', 'rains', 'rained'], 2, 'Conditional type 1: If + present simple, ... will + V.', ['Sai — would rain không dùng trong mệnh đề if của câu điều kiện loại 1.', 'Sai — will rain không dùng trong mệnh đề if; "will" thuộc mệnh đề chính.', 'Đúng — conditional type 1: If + present simple, ... will + V (rains).', 'Sai — rained (quá khứ) thuộc điều kiện loại 2, không hợp với "will cancel".']),
    Q('"If I ___ you, I would buy that newspaper."', ['were', 'was (sai số ít quy ước trong điều kiện loại 2)', 'be (động từ nguyên thể, sai dạng)', 'am (hiện tại đơn, không dùng trong if loại 2)'], 0, 'Conditional type 2: If I were you (giả định không thực ở hiện tại).', ['Đúng — conditional type 2: If I were you (giả định không thực ở hiện tại).', 'Sai — was sai theo quy ước điều kiện loại 2 (dùng "were" cho mọi ngôi).', 'Sai — be (nguyên thể) sai dạng trong mệnh đề if.', 'Sai — am (hiện tại đơn) không dùng trong if loại 2.']),
    Q('"Social media" refers to ___.', ['television channels', 'printed newspapers', 'radio stations', 'online platforms for sharing content'], 3, 'Social media - mạng xã hội: nền tảng trực tuyến để chia sẻ nội dung.', ['Sai — social media không phải kênh truyền hình.', 'Sai — social media không phải báo in.', 'Sai — social media không phải đài phát thanh.', 'Đúng — social media là nền tảng trực tuyến để chia sẻ nội dung.']),
    Q('Synonym of "broadcast" is ___.', ['censor (kiểm duyệt — liên quan media nhưng khác nghĩa)', 'delete', 'publish (xuất bản — chỉ cho báo in, không phải phát sóng)', 'transmit'], 3, 'Broadcast (phát sóng) = transmit (truyền).', ['Sai — censor (kiểm duyệt) liên quan media nhưng khác nghĩa với phát sóng.', 'Sai — delete (xoá) trái nghĩa với phát/truyền đi.', 'Sai — publish (xuất bản) dùng cho báo in, không phải phát sóng.', 'Đúng — broadcast (phát sóng) = transmit (truyền đi).']),
    Q('"A ___ is someone who writes news articles for a newspaper."', ['journalist', 'reader', 'publisher', 'editor'], 0, 'Journalist - nhà báo, người viết tin bài.', ['Đúng — journalist là nhà báo, người viết tin bài.', 'Sai — reader (độc giả) là người đọc, không viết tin.', 'Sai — publisher (nhà xuất bản) là người phát hành, không viết bài.', 'Sai — editor (biên tập viên) chỉnh sửa bài, không phải người viết tin chính.']),
    Q('"If she had a smartphone, she ___ check her email anywhere."', ['could (khả năng, dùng được nhưng nhấn quá ít)', 'would', 'can (hiện tại, sai vì if had → would)', 'will (loại 1, sai vì if had)'], 1, 'Conditional type 2: If + V-ed, ... would + V (giả định không thực hiện tại).', ['Sai — could (khả năng) dùng được nhưng nhấn quá nhẹ; "would" phù hợp hơn cho kết quả giả định.', 'Đúng — conditional type 2: If + V-ed, ... would + V (giả định không thực hiện tại).', 'Sai — can (hiện tại) không hợp; if had → would.', 'Sai — will thuộc loại 1, không hợp với "if she had".']),
  ]),

  M(8, 'Unit 4 — Conditionals 3 + Mixed', [
    Q('"If I ___ harder, I would have passed the exam."', ['study (hiện tại đơn, không khớp loại 3)', 'have studied', 'had studied', 'studied'], 2, 'Type 3: If + had V3, ... would have V3 (giả định trái với quá khứ).', ['Sai — study (hiện tại đơn) không hợp loại 3.', 'Sai — have studied (hiện tại hoàn thành) không dùng trong if loại 3; cần had V3.', 'Đúng — type 3: If + had V3, ... would have V3 (giả định trái quá khứ).', 'Sai — studied (quá khứ đơn) thuộc loại 2, không hợp "would have passed".']),
    Q('"If she had taken the job, she ___ rich now."', ['would be', 'would have been', 'will be', 'is (hiện tại đơn, sai cấu trúc điều kiện hỗn hợp)'], 0, 'Mixed conditional: If + had V3 (quá khứ), ... would V (hiện tại).', ['Đúng — mixed conditional: If + had V3 (quá khứ), ... would V (hiện tại) — "now".', 'Sai — would have been chỉ kết quả quá khứ; ở đây "now" cần kết quả hiện tại.', 'Sai — will be thuộc loại 1, không hợp với "if she had taken".', 'Sai — is (hiện tại đơn) sai cấu trúc điều kiện hỗn hợp.']),
    Q('"If I were taller, I ___ a basketball player."', ['am (hiện tại đơn, sai vì if were)', 'would have been', 'will be', 'would be'], 3, 'Type 2: If + V-ed, ... would + V (kết quả ở hiện tại).', ['Sai — am (hiện tại đơn) không hợp khi mệnh đề if là "were".', 'Sai — would have been chỉ kết quả quá khứ; câu này kết quả hiện tại.', 'Sai — will be thuộc loại 1, không hợp "if I were".', 'Đúng — type 2: If + V-ed (were), ... would + V (kết quả hiện tại).']),
    Q('"___ I known about the meeting, I would have come."', ['Should', 'Were (đảo ngữ loại 2, sai vì có known V3)', 'If (giữ if thì không đảo ngữ trợ động từ)', 'Had'], 3, 'Đảo ngữ type 3: Had + S + V3, ... (lược bỏ "if").', ['Sai — Should không hợp với "known V3"; đảo ngữ loại 3 dùng "Had".', 'Sai — Were dùng cho đảo ngữ loại 2, không hợp khi có "known V3".', 'Sai — giữ "If" thì không đảo ngữ trợ động từ ra đầu.', 'Đúng — đảo ngữ type 3: Had + S + V3, ... (lược bỏ "if").']),
    Q('"___ it not been for her help, I would have failed."', ['Had', 'Were (đảo ngữ loại 2, sai vì có been V3)', 'Should', 'If (giữ if thì không lược had ra đầu)'], 0, 'Đảo ngữ "If it had not been for X" = "Had it not been for X" (nếu không nhờ).', ['Đúng — "If it had not been for X" = "Had it not been for X" (nếu không nhờ).', 'Sai — Were dùng cho loại 2, không hợp khi có "been V3".', 'Sai — Should không tạo được cấu trúc này với "been".', 'Sai — giữ "If" thì không lược "had" ra đầu câu.']),
    Q('Conditional type 0 expresses ___.', ['future plans', 'imaginary present', 'imaginary past', 'general truths/facts'], 3, 'Type 0: If + present, ... + present - sự thật, quy luật (If you heat water, it boils).', ['Sai — kế hoạch tương lai thuộc loại 1, không phải loại 0.', 'Sai — giả định hiện tại không thực thuộc loại 2.', 'Sai — giả định quá khứ thuộc loại 3.', 'Đúng — type 0: If + present, ... + present — sự thật, quy luật (water boils).']),
  ]),

  M(9, 'Unit 5 — Cultural Identity (Vocabulary + Modal verbs)', [
    Q('"You ___ remove your shoes when entering a Vietnamese house."', ['might (có thể — quá yếu cho phong tục)', 'should', 'can (có khả năng — không phải lời khuyên)', 'need (cần — thiếu to trước remove)'], 1, 'Should - lời khuyên/phong tục lịch sự.', ['Sai — might (có thể) quá yếu cho một phong tục nên làm.', 'Đúng — should diễn tả lời khuyên/phong tục lịch sự.', 'Sai — can chỉ khả năng, không phải lời khuyên.', 'Sai — need thiếu "to" trước "remove" (need to remove).']),
    Q('"Cultural identity" refers to ___.', ['religion only', 'sense of belonging to a culture/community', 'national flag only', 'language only'], 1, 'Cultural identity - bản sắc văn hoá: cảm thức thuộc về một nền văn hoá/cộng đồng.', ['Sai — bản sắc văn hoá không chỉ gói gọn ở tôn giáo.', 'Đúng — cultural identity là cảm thức thuộc về một nền văn hoá/cộng đồng.', 'Sai — không chỉ là quốc kì.', 'Sai — không chỉ là ngôn ngữ.']),
    Q('"You ___ be quiet in the library." (obligation)', ['can (có thể — chỉ khả năng, không bắt buộc)', 'could (có thể — quá khứ của can, không bắt buộc)', 'must', 'may (được phép — chỉ sự cho phép)'], 2, 'Must - bắt buộc, quy định.', ['Sai — can chỉ khả năng, không diễn tả nghĩa vụ bắt buộc.', 'Sai — could là quá khứ của can, không diễn tả bắt buộc.', 'Đúng — must diễn tả nghĩa vụ, quy định bắt buộc.', 'Sai — may chỉ sự cho phép, không phải bắt buộc.']),
    Q('"He ___ speak five languages fluently."', ['must (chắc chắn — suy đoán, không phải khả năng)', 'will (sẽ — tương lai, không phải khả năng)', 'can', 'should'], 2, 'Can - khả năng.', ['Sai — must (chắc chắn) là suy đoán, không phải khả năng làm việc.', 'Sai — will (sẽ) là tương lai, không diễn tả khả năng.', 'Đúng — can diễn tả khả năng (nói được 5 thứ tiếng).', 'Sai — should (nên) là lời khuyên, không phải khả năng.']),
    Q('Synonym of "preserve" is ___.', ['protect', 'preserve nghĩa là sell (bán đi — trái nghĩa)', 'ignore', 'destroy'], 0, 'Preserve = protect (bảo tồn, giữ gìn).', ['Đúng — preserve = protect (bảo tồn, giữ gìn).', 'Sai — preserve không có nghĩa "sell"; "bán đi" là trái nghĩa.', 'Sai — ignore (phớt lờ) không liên quan đến bảo tồn.', 'Sai — destroy (phá huỷ) là trái nghĩa.']),
    Q('"In some cultures, it is rude ___ during meals."', ['talked loudly', 'talking loudly', 'to talk loudly', 'talk loudly'], 2, 'Cấu trúc "It is + adj + to V".', ['Sai — talked loudly (V3/quá khứ) sai dạng sau "It is + adj".', 'Sai — talking loudly (V-ing) không hợp với "It is + adj + to V".', 'Đúng — cấu trúc "It is + adj + to V" (to talk loudly).', 'Sai — talk loudly thiếu "to" trong cấu trúc "It is + adj + to V".']),
  ]),

  M(10, 'Unit 5 — Modal perfect (must/should/could have V3)', [
    Q('"He looks tired. He ___ all night."', ['must work', 'must have worked', 'must working', 'must to work'], 1, 'Must + have + V3 - suy đoán chắc chắn về quá khứ.', ['Sai — must work sai dạng; suy đoán quá khứ cần have + V3.', 'Đúng — must + have + V3 (must have worked) — suy đoán chắc chắn về quá khứ.', 'Sai — must working sai dạng; phải have worked.', 'Sai — must to work sai dạng; modal không đi với "to".']),
    Q('"You ___ told me earlier. Now it\'s too late."', ['should be', 'should have', 'should', 'must have'], 1, 'Should have V3 - đáng lẽ phải làm (nhưng đã không) - hối tiếc/trách móc nhẹ.', ['Sai — should be sai dạng; hối tiếc quá khứ cần should have V3.', 'Đúng — should have V3 (should have told) — đáng lẽ phải làm nhưng đã không.', 'Sai — should đứng một mình không diễn tả hối tiếc quá khứ.', 'Sai — must have là suy đoán chắc chắn, không phải trách móc/hối tiếc.']),
    Q('"I ___ have left my keys at home; I can\'t find them."', ['should', 'can (HS nhầm dùng can have — sai cấu trúc)', 'might', 'must (chắc chắn đã, quá mạnh khi nói can\'t find)'], 2, 'Might/could/may + have V3 - phỏng đoán không chắc về quá khứ.', ['Sai — should have không hợp; ngữ cảnh là phỏng đoán chứ không phải lời khuyên.', 'Sai — "can have" không tồn tại; phải dùng might/could/may have.', 'Đúng — might/could/may + have V3 — phỏng đoán không chắc về quá khứ.', 'Sai — must have (chắc chắn đã) quá mạnh khi người nói "can\'t find them".']),
    Q('"She ___ have known the answer; she didn\'t prepare."', ['might (có thể đã biết — sai vì cô ấy không chuẩn bị)', 'can\'t', 'must (chắc chắn đã biết — trái với didn\'t prepare)', 'should'], 1, 'Can\'t/couldn\'t + have V3 - chắc chắn không xảy ra trong quá khứ.', ['Sai — might (có thể đã biết) không hợp vì cô ấy không chuẩn bị.', 'Đúng — can\'t/couldn\'t + have V3 — chắc chắn không xảy ra trong quá khứ.', 'Sai — must (chắc chắn đã biết) trái với "didn\'t prepare".', 'Sai — should have là trách móc, không phải suy đoán phủ định.']),
    Q('"You ___ have eaten so much. Now you feel sick."', ['won\'t (will not — sai vì hành động đã xảy ra)', 'shouldn\'t', 'can\'t (không thể đã — sai vì hành động đã xảy ra)', 'must not'], 1, 'Shouldn\'t have V3 - đáng lẽ không nên (đã làm rồi - hối tiếc).', ['Sai — won\'t (tương lai phủ định) sai vì hành động đã xảy ra rồi.', 'Đúng — shouldn\'t have V3 — đáng lẽ không nên (đã làm rồi, hối tiếc).', 'Sai — can\'t have V3 nghĩa "không thể đã", sai vì hành động đã xảy ra.', 'Sai — must not là cấm ở hiện tại, không phải hối tiếc quá khứ.']),
    Q('"They ___ have arrived already; the lights are on."', ['must', 'wouldn\'t', 'should', 'can\'t (không thể đã — trái với bằng chứng đèn sáng)'], 0, 'Must have V3 - suy đoán chắc chắn dựa trên bằng chứng (đèn sáng).', ['Đúng — must have V3 — suy đoán chắc chắn dựa trên bằng chứng (đèn sáng).', 'Sai — wouldn\'t have không hợp ngữ cảnh suy đoán dựa bằng chứng.', 'Sai — should have là trách móc, không phải suy đoán chắc chắn.', 'Sai — can\'t have (không thể đã) trái với bằng chứng đèn đang sáng.']),
  ]),

  M(11, 'Unit 6 — Endangered Species (Vocabulary + Relative clauses)', [
    Q('"The Saola is a rare animal ___ lives only in Vietnam and Laos."', ['whose (sở hữu cách, sai vì chủ ngữ)', 'where (trạng ngữ nơi chốn, không thay chủ ngữ)', 'who (dùng cho người, không phải động vật)', 'which'], 3, 'Which - đại từ quan hệ cho vật/động vật làm chủ ngữ.', ['Sai — whose là sở hữu cách, không thay được vai trò chủ ngữ.', 'Sai — where là trạng ngữ nơi chốn, không thay chủ ngữ.', 'Sai — who dùng cho người, không phải động vật.', 'Đúng — which là đại từ quan hệ cho vật/động vật làm chủ ngữ.']),
    Q('"Endangered species" are species that ___.', ['are common', 'have recovered', 'are extinct', 'are at risk of extinction'], 3, 'Endangered - có nguy cơ tuyệt chủng (nhưng chưa tuyệt chủng - extinct).', ['Sai — endangered không phải loài phổ biến.', 'Sai — endangered không phải loài đã phục hồi.', 'Sai — extinct là đã tuyệt chủng; endangered chỉ có nguy cơ.', 'Đúng — endangered là loài có nguy cơ tuyệt chủng.']),
    Q('"This is the reserve ___ many rare animals are protected."', ['which (chủ ngữ/tân ngữ vật, không phải trạng ngữ nơi chốn)', 'who (dùng cho người, không phải nơi chốn)', 'where', 'that (không thay được for which/where)'], 2, 'Where - trạng ngữ chỉ nơi chốn.', ['Sai — which làm chủ ngữ/tân ngữ cho vật, không phải trạng ngữ nơi chốn.', 'Sai — who dùng cho người, không chỉ nơi chốn.', 'Đúng — where là trạng ngữ chỉ nơi chốn (in the reserve).', 'Sai — that không thay được for which/where ở đây.']),
    Q('"The scientist ___ research has saved many species is famous."', ['who (chủ ngữ chỉ người, sai vì cần sở hữu)', 'whom (tân ngữ chỉ người, sai chức năng)', 'whose', 'which (chỉ vật, sai vì là người)'], 2, 'Whose - sở hữu cách dùng cho người (whose research = his research).', ['Sai — who làm chủ ngữ chỉ người, không diễn tả sở hữu.', 'Sai — whom là tân ngữ chỉ người, sai chức năng (cần sở hữu).', 'Đúng — whose là sở hữu cách cho người (whose research = his research).', 'Sai — which chỉ vật, sai vì đây là người (scientist).']),
    Q('"Deforestation" means ___.', ['planting trees', 'protecting forests', 'growing crops', 'cutting down forests'], 3, 'Deforestation - phá rừng, chặt phá rừng.', ['Sai — trồng cây là trái nghĩa với phá rừng.', 'Sai — bảo vệ rừng là trái nghĩa.', 'Sai — trồng trọt không phải nghĩa của deforestation.', 'Đúng — deforestation là phá rừng, chặt phá rừng.']),
    Q('Defining vs non-defining relative clauses differ in ___.', ['length', 'meaning', 'verb tense (thì động từ — không liên quan đến phân loại mệnh đề)', 'use of commas'], 3, 'Non-defining clause được đặt giữa hai dấu phẩy, defining thì không.', ['Sai — độ dài không phải tiêu chí phân biệt hai loại mệnh đề.', 'Sai — bản thân nghĩa không phải tiêu chí hình thức để phân biệt.', 'Sai — thì động từ không liên quan đến phân loại mệnh đề quan hệ.', 'Đúng — non-defining đặt giữa hai dấu phẩy, defining thì không.']),
  ]),

  M(12, 'Unit 6 — Reduced relative clauses', [
    Q('"The man ___ standing over there is my teacher." (Rút gọn từ "who is standing")', ['is (cần is standing nhưng rút gọn bỏ "who is")', 'standing', 'was (quá khứ, không khớp với hiện tại)', 'to stand'], 1, 'Rút gọn mệnh đề chủ động: bỏ "who/which is" → giữ V-ing.', ['Sai — chỉ "is" không đủ; rút gọn bỏ "who is" và giữ V-ing.', 'Đúng — rút gọn mệnh đề chủ động: bỏ "who/which is" → giữ V-ing (standing).', 'Sai — was (quá khứ) không khớp với hiện tại "is my teacher".', 'Sai — to stand sai dạng rút gọn; phải là V-ing.']),
    Q('"The book ___ on the shelf belongs to me." (Rút gọn "which is placed")', ['to place', 'places', 'placed', 'placing'], 2, 'Rút gọn mệnh đề bị động: bỏ "which/who is" → giữ V-ed/V3.', ['Sai — to place sai dạng trong rút gọn bị động.', 'Sai — places (chủ động hiện tại) sai; sách "được đặt" nên dùng bị động.', 'Đúng — rút gọn mệnh đề bị động: bỏ "which is" → giữ V3 (placed).', 'Sai — placing (V-ing chủ động) sai; sách là đối tượng được đặt.']),
    Q('"The candidates ___ for the job will be informed soon."', ['to select', 'select', 'selected', 'selecting'], 2, 'Bị động (được chọn) → V3 (selected).', ['Sai — to select sai dạng rút gọn ở đây.', 'Sai — select (chủ động) sai; ứng viên "được chọn" nên dùng bị động.', 'Đúng — bị động (được chọn) → V3 (selected).', 'Sai — selecting (V-ing chủ động) sai; ứng viên là đối tượng được chọn.']),
    Q('"The first person ___ this competition will win a prize."', ['winning', 'to win', 'won (quá khứ đơn, sai sau "the first person")', 'wins (hiện tại đơn, sai sau "the first person")'], 1, 'The first/last/only + to V (nguyên thể).', ['Sai — winning (V-ing) không dùng sau "the first person".', 'Đúng — the first/last/only + to V (to win).', 'Sai — won (quá khứ đơn) sai sau "the first person".', 'Sai — wins (hiện tại đơn) sai sau "the first person".']),
    Q('"Animals ___ in the wild are often more aggressive."', ['lived (V3 chỉ dùng cho bị động rút gọn)', 'to live', 'living', 'live (động từ nguyên thể, sai cấu trúc rút gọn)'], 2, 'Chủ động (sống) → V-ing (living).', ['Sai — lived (V3) chỉ dùng cho rút gọn bị động; ở đây nghĩa chủ động.', 'Sai — to live sai dạng rút gọn chủ động ở đây.', 'Đúng — chủ động (sống) → V-ing (living).', 'Sai — live (nguyên thể) sai cấu trúc rút gọn.']),
    Q('"There are many things ___ in this museum."', ['to see', 'to seeing', 'seeing', 'seen (V3 bị động, sai vì có nghĩa chủ động "để xem")'], 0, 'To + V chỉ mục đích/đặc điểm sau "things/something".', ['Đúng — to + V chỉ mục đích/đặc điểm sau "things/something" (things to see).', 'Sai — to seeing sai; sau "to" dùng nguyên thể (to see).', 'Sai — seeing (V-ing) không diễn tả "để xem" sau "things".', 'Sai — seen (V3 bị động) sai vì nghĩa ở đây là chủ động "để xem".']),
  ]),

  M(13, 'Unit 7 — Artificial Intelligence (Vocabulary + Future tenses)', [
    Q('"By 2030, AI ___ many human tasks."', ['will have replaced', 'replaces', 'is replacing', 'will replace'], 0, '"By + future time" → future perfect (will have + V3).', ['Đúng — "by + mốc tương lai" → future perfect (will have replaced).', 'Sai — replaces (hiện tại đơn) không khớp mốc tương lai "by 2030".', 'Sai — is replacing (hiện tại tiếp diễn) không khớp "by 2030".', 'Sai — will replace (tương lai đơn) không nhấn sự hoàn tất trước mốc.']),
    Q('"Artificial Intelligence" refers to ___.', ['human brains', 'machines that simulate human intelligence', 'only robots', 'natural intelligence'], 1, 'AI - trí tuệ nhân tạo: máy mô phỏng trí thông minh con người.', ['Sai — AI không phải bộ não người.', 'Đúng — AI là máy mô phỏng trí thông minh con người.', 'Sai — AI không chỉ giới hạn ở robot.', 'Sai — natural intelligence là trí thông minh tự nhiên, trái nghĩa với "artificial".']),
    Q('"At this time next year, I ___ at a tech company."', ['will be working', 'work (hiện tại đơn, không khớp "at this time next year")', 'will work', 'am working'], 0, '"At this time + future" → future continuous (will be V-ing).', ['Đúng — "at this time + tương lai" → future continuous (will be working).', 'Sai — work (hiện tại đơn) không khớp "at this time next year".', 'Sai — will work (tương lai đơn) không diễn tả việc đang diễn ra tại thời điểm tương lai.', 'Sai — am working (hiện tại tiếp diễn) không khớp mốc tương lai.']),
    Q('"I think robots ___ humans in many jobs soon."', ['replaced', 'replace', 'are replacing', 'will replace'], 3, '"I think + future" → will + V (dự đoán).', ['Sai — replaced (quá khứ) không hợp với "soon".', 'Sai — replace (hiện tại đơn) không diễn tả dự đoán tương lai.', 'Sai — are replacing (hiện tại tiếp diễn) không hợp với "soon".', 'Đúng — "I think + tương lai" → will + V (dự đoán).']),
    Q('Synonym of "automate" is ___.', ['manually do', 'slow down', 'mechanise', 'complicate'], 2, 'Automate (tự động hoá) = mechanise (cơ giới hoá).', ['Sai — manually do (làm thủ công) là trái nghĩa với tự động hoá.', 'Sai — slow down (làm chậm lại) không liên quan.', 'Đúng — automate = mechanise (cơ giới hoá/tự động hoá).', 'Sai — complicate (làm phức tạp) không phải nghĩa của automate.']),
    Q('"We ___ a new AI system next month."', ['will launch', 'are launching', 'launched', 'launch'], 0, 'Will + V cho kế hoạch tương lai chưa chắc chắn; "are launching" cũng đúng nếu sắp xếp.', ['Đúng — will + V cho kế hoạch tương lai (will launch).', 'Sai — are launching đúng nếu lịch đã sắp xếp, nhưng phương án "will launch" phù hợp nhất ở đây.', 'Sai — launched (quá khứ) không khớp "next month".', 'Sai — launch (hiện tại đơn) không diễn tả kế hoạch tương lai.']),
  ]),

  M(14, 'Unit 7 — Inversion (Hardly, Not until, No sooner)', [
    Q('"Hardly ___ when the phone rang."', ['did I sit', 'I sat (không đảo ngữ sau Hardly)', 'had I sat', 'I had sat'], 2, 'Hardly + had + S + V3 ... when + S + V-ed: vừa mới ... thì ...', ['Sai — did I sit sai dạng; sau "Hardly" đảo ngữ dùng had + S + V3.', 'Sai — I sat không đảo ngữ sau "Hardly".', 'Đúng — Hardly + had + S + V3... when + S + V-ed (had I sat).', 'Sai — I had sat không đảo trợ động từ ra trước chủ ngữ sau "Hardly".']),
    Q('"Not until 1986 ___ economic reforms in Vietnam."', ['did ... begin', 'did begin', 'did begin', 'began (không đảo ngữ sau Not until)'], 0, 'Not until + time + did + S + V (đảo ngữ).', ['Đúng — Not until + time + did + S + V (đảo ngữ): did... begin.', 'Sai — did begin thiếu chủ ngữ giữa "did" và "begin".', 'Sai — did begin thiếu chủ ngữ; cấu trúc cần did + S + V.', 'Sai — began không đảo ngữ sau "Not until".']),
    Q('"No sooner ___ home than it started to rain."', ['had I arrived', 'I arrived', 'did I arrive', 'I had arrived'], 0, 'No sooner + had + S + V3 ... than + S + V-ed.', ['Đúng — No sooner + had + S + V3... than + S + V-ed (had I arrived).', 'Sai — I arrived không đảo ngữ sau "No sooner".', 'Sai — did I arrive sai dạng; "No sooner" dùng had + S + V3.', 'Sai — I had arrived không đảo trợ động từ ra trước chủ ngữ.']),
    Q('"Never ___ such a beautiful sight!"', ['do I see', 'I had seen', 'I have seen', 'have I seen'], 3, 'Never + have + S + V3 (đảo ngữ).', ['Sai — do I see sai thì; "Never" + kinh nghiệm dùng have + S + V3.', 'Sai — I had seen không đảo ngữ sau "Never".', 'Sai — I have seen không đảo trợ động từ ra trước chủ ngữ.', 'Đúng — Never + have + S + V3 (have I seen) — đảo ngữ.']),
    Q('"Only by working hard ___ achieve success."', ['could you', 'can you', 'you can', 'you could'], 1, 'Only by + V-ing + can/could + S + V (đảo ngữ).', ['Sai — could you là quá khứ, không hợp ngữ cảnh chung ở hiện tại.', 'Đúng — Only by + V-ing + can/could + S + V (đảo ngữ): can you.', 'Sai — you can không đảo trợ động từ ra trước chủ ngữ.', 'Sai — you could không đảo ngữ và sai thì.']),
    Q('"Seldom ___ to the cinema these days."', ['do I go', 'I go (không đảo ngữ sau Seldom)', 'go I (đảo ngữ sai, thiếu trợ động từ do)', 'I do go'], 0, 'Seldom/rarely + do/does + S + V (đảo ngữ).', ['Đúng — Seldom/rarely + do/does + S + V (đảo ngữ): do I go.', 'Sai — I go không đảo ngữ sau "Seldom".', 'Sai — go I thiếu trợ động từ "do" trong đảo ngữ.', 'Sai — I do go không đảo trợ động từ ra trước chủ ngữ.']),
  ]),

  M(15, 'Unit 8 — The World of Work (Vocabulary + Articles)', [
    Q('"She wants to become ___ engineer."', ['the (mạo từ xác định, sai vì engineer chưa xác định)', 'a (mạo từ trước phụ âm, sai vì engineer bắt đầu nguyên âm)', '∅ (no article — sai vì cần mạo từ trước nghề nghiệp số ít)', 'an'], 3, 'An - đứng trước danh từ bắt đầu bằng nguyên âm (engineer).', ['Sai — "the" là mạo từ xác định, sai vì "engineer" chưa xác định.', 'Sai — "a" dùng trước phụ âm; "engineer" bắt đầu bằng nguyên âm.', 'Sai — nghề nghiệp số ít cần mạo từ; không thể bỏ trống.', 'Đúng — "an" đứng trước danh từ bắt đầu bằng nguyên âm (engineer).']),
    Q('"___ unemployment rate has risen recently."', ['An (mạo từ trước nguyên âm, sai vì unemployment đọc /ʌn/)', 'The', 'A (sai vì unemployment bắt đầu nguyên âm)', '∅ (no article — sai vì có "rate" xác định)'], 1, 'The - dùng cho đối tượng xác định (tỉ lệ thất nghiệp cụ thể).', ['Sai — "An" sai vì "the rate" là đối tượng xác định, không phải mạo từ không xác định.', 'Đúng — "the" dùng cho đối tượng xác định (tỉ lệ thất nghiệp cụ thể).', 'Sai — "A" sai vì cần mạo từ xác định cho "rate" cụ thể.', 'Sai — bỏ trống sai vì "the rate" cần mạo từ xác định.']),
    Q('A "resume" or "CV" is ___.', ['a document summarising one\'s qualifications', 'a job advertisement', 'a contract', 'a letter of complaint'], 0, 'CV/Resume - tài liệu tóm tắt trình độ, kinh nghiệm xin việc.', ['Đúng — CV/Resume là tài liệu tóm tắt trình độ, kinh nghiệm xin việc.', 'Sai — đó là quảng cáo tuyển dụng, không phải CV.', 'Sai — đó là hợp đồng, không phải CV.', 'Sai — đó là thư khiếu nại, không phải CV.']),
    Q('"I went to ___ university to study English."', ['∅ (no article — sai vì cần mạo từ trước university số ít)', 'the (mạo từ xác định, sai vì chỉ một trường bất kỳ)', 'an (mạo từ trước nguyên âm, sai vì /j/ là phụ âm)', 'a'], 3, '"University" bắt đầu bằng âm /j/ - phụ âm → dùng "a".', ['Sai — bỏ trống sai; "university" số ít đếm được cần mạo từ.', 'Sai — "the" sai vì nói tới một trường bất kì, không xác định.', 'Sai — "an" sai vì "university" bắt đầu bằng âm /j/ là phụ âm.', 'Đúng — "university" bắt đầu bằng âm /j/ (phụ âm) → dùng "a".']),
    Q('Synonym of "salary" is ___.', ['fee (phí dịch vụ — không phải lương)', 'tip (tiền boa — không phải lương cố định)', 'fine (tiền phạt — trái nghĩa với salary)', 'wage'], 3, 'Salary (lương cố định) ≈ wage (lương theo giờ/tuần).', ['Sai — fee là phí dịch vụ, không phải lương.', 'Sai — tip là tiền boa, không phải lương cố định.', 'Sai — fine là tiền phạt, trái nghĩa.', 'Đúng — salary (lương cố định) ≈ wage (lương theo giờ/tuần).']),
    Q('"___ honesty is the best policy."', ['An (mạo từ trước nguyên âm — sai vì honesty trừu tượng)', '∅', 'The (mạo từ xác định — sai vì nói chung chung)', 'A (mạo từ trước phụ âm — sai vì honesty trừu tượng)'], 1, 'Danh từ trừu tượng nói chung không cần mạo từ.', ['Sai — "An" sai vì honesty là danh từ trừu tượng nói chung.', 'Đúng — danh từ trừu tượng nói chung không cần mạo từ.', 'Sai — "The" sai vì đang nói chung chung, không cụ thể.', 'Sai — "A" sai vì honesty là danh từ trừu tượng không đếm được.']),
  ]),

  M(16, 'Unit 8 — Phrasal verbs at work', [
    Q('"She has decided to ___ applying for the job."', ['look forward', 'take after', 'go on (tiếp tục — trái nghĩa với decided)', 'give up'], 3, 'Give up - từ bỏ.', ['Sai — look forward (to) nghĩa mong chờ, không hợp với "decided to".', 'Sai — take after nghĩa "giống ai", không hợp ngữ cảnh.', 'Sai — go on (tiếp tục) trái nghĩa với việc đã "decided to" dừng.', 'Đúng — give up = từ bỏ.']),
    Q('"He ___ his father in appearance."', ['takes in', 'takes up', 'takes after', 'takes off'], 2, 'Take after - giống (cha mẹ về ngoại hình/tính cách).', ['Sai — takes in nghĩa tiếp thu/lừa, không phải giống ai.', 'Sai — takes up nghĩa bắt đầu (sở thích), không phải giống ai.', 'Đúng — take after = giống (cha mẹ về ngoại hình/tính cách).', 'Sai — takes off nghĩa cất cánh/cởi ra, nhầm nghĩa.']),
    Q('"The interview was ___ until Monday."', ['put up', 'put down', 'put on', 'put off'], 3, 'Put off - hoãn lại.', ['Sai — put up nghĩa dựng lên/cho ở trọ, nhầm nghĩa.', 'Sai — put down nghĩa đặt xuống/hạ bệ, nhầm nghĩa.', 'Sai — put on nghĩa mặc vào/bật lên, nhầm nghĩa.', 'Đúng — put off = hoãn lại.']),
    Q('"Please ___ this form before submitting."', ['fill up', 'fill in', 'both A and C', 'fill out'], 2, 'Fill in/fill out - điền thông tin vào (form).', ['Sai — fill up nghĩa đổ đầy, không dùng cho điền form.', 'Sai — fill in đúng nhưng đáp án bao gồm cả fill out nên phải chọn "both".', 'Đúng — fill in/fill out đều nghĩa điền thông tin vào form.', 'Sai — fill out đúng nhưng đáp án bao gồm cả fill in nên phải chọn "both".']),
    Q('"He was ___ from the company due to misconduct."', ['laid up', 'laid down', 'laid off', 'laid out'], 2, 'Laid off - bị cho nghỉ việc (thường vì lí do kinh tế); fired - bị sa thải có lỗi.', ['Sai — laid up nghĩa nằm liệt (ốm), nhầm nghĩa.', 'Sai — laid down nghĩa đặt ra (quy định), nhầm nghĩa.', 'Đúng — laid off = bị cho nghỉ việc (thường vì lí do kinh tế).', 'Sai — laid out nghĩa bố trí/trình bày, nhầm nghĩa.']),
    Q('"I\'m looking ___ to hearing from you."', ['up (HS nhầm với look up — tra cứu)', 'after (HS nhầm với look after — chăm sóc)', 'forward', 'for (HS nhầm với look for — tìm kiếm)'], 2, 'Look forward to + V-ing/N - mong chờ.', ['Sai — "up" nhầm với look up (tra cứu).', 'Sai — "after" nhầm với look after (chăm sóc).', 'Đúng — look forward to + V-ing/N = mong chờ.', 'Sai — "for" nhầm với look for (tìm kiếm).']),
  ]),

  M(17, 'Unit 9 — Choosing a Career (Cleft sentences)', [
    Q('"It was John ___ helped me with my homework."', ['which (đại từ quan hệ chỉ vật, không phải cleft)', 'where (trạng ngữ nơi chốn, không hợp ngữ cảnh)', 'that', 'what (không dùng trong cleft sau "It was + N")'], 2, 'Cleft "It is/was + N + that + V": who/that cho người.', ['Sai — which là đại từ quan hệ chỉ vật, không phải đại từ cleft cho người.', 'Sai — where là trạng ngữ nơi chốn, không hợp ngữ cảnh.', 'Đúng — cleft "It is/was + N + that...": who/that cho người (John).', 'Sai — what không dùng sau "It was + N" trong cleft.']),
    Q('"It is ___ that motivates me most." (Nhấn mạnh chính tiền bạc)', ['by money', 'money', 'to money', 'for money'], 1, 'It is + nhấn mạnh + that + S V: "money" được nhấn mạnh.', ['Sai — by money thừa giới từ; cleft nhấn mạnh trực tiếp danh từ.', 'Đúng — It is + nhấn mạnh + that + S V: "money" được nhấn mạnh.', 'Sai — to money thừa giới từ trong cấu trúc cleft.', 'Sai — for money thừa giới từ; phải nhấn mạnh trực tiếp "money".']),
    Q('"___ I really want is a stable job."', ['Where (trạng ngữ nơi chốn — không hợp What-cleft)', 'Which (đại từ quan hệ — không mở đầu được cleft)', 'What', 'That (không dùng đầu câu trong cleft này)'], 2, 'What-cleft: What + clause + is/are + thing emphasised.', ['Sai — Where là trạng ngữ nơi chốn, không mở đầu what-cleft.', 'Sai — Which là đại từ quan hệ, không mở đầu được cleft.', 'Đúng — what-cleft: What + clause + is/are + thing emphasised.', 'Sai — That không dùng đầu câu trong cleft này.']),
    Q('"It was in 2020 ___ she started her own business."', ['which (đại từ quan hệ vật — không thay cho thời gian trong cleft)', 'that', 'when (HS nhầm vì có thời gian, nhưng cleft chuẩn dùng that)', 'where (chỉ nơi chốn — sai vì là thời gian)'], 1, 'Cleft với thời gian: it was + time + that + ...', ['Sai — which chỉ vật, không thay cho mốc thời gian trong cleft.', 'Đúng — cleft với thời gian: It was + time + that + ... (that).', 'Sai — when bị nhầm vì có thời gian, nhưng cleft chuẩn dùng "that".', 'Sai — where chỉ nơi chốn, sai vì đây là thời gian.']),
    Q('"It is teamwork ___ leads to success in this company."', ['where (trạng ngữ nơi chốn — sai vì teamwork không phải nơi)', 'what (không dùng trong It-cleft chuẩn)', 'that', 'who (dành cho người — teamwork không phải người)'], 2, 'It-cleft với "teamwork" (không phải người) → that/which.', ['Sai — where chỉ nơi chốn; "teamwork" không phải nơi.', 'Sai — what không dùng trong It-cleft chuẩn.', 'Đúng — It-cleft với "teamwork" (không phải người) → that.', 'Sai — who dành cho người; "teamwork" không phải người.']),
    Q('"All ___ matters is your effort."', ['that', 'who (dùng cho người — sai vì all chỉ vật)', 'what (không dùng sau all)', 'which (không dùng sau all)'], 0, 'Sau "all" dùng "that" (không dùng "what").', ['Đúng — sau "all" dùng "that" (không dùng "what").', 'Sai — who dùng cho người; "all" ở đây chỉ vật/sự việc.', 'Sai — what không dùng sau "all".', 'Sai — which không dùng sau "all".']),
  ]),

  M(18, 'Ôn tập HK1 — Mid-term review', [
    Q('"If I ___ enough money, I would buy a new laptop."', ['have (hiện tại đơn — sai cấu trúc if loại 2)', 'had', 'would have', 'will have'], 1, 'Type 2: If + V-ed (had), ... would + V.', ['Sai — have (hiện tại đơn) sai cấu trúc if loại 2.', 'Đúng — type 2: If + V-ed (had), ... would + V.', 'Sai — would have thuộc loại 3, không hợp với "would buy".', 'Sai — will have thuộc loại 1, không hợp với "would buy".']),
    Q('"He said he ___ working there since 2018."', ['is (hiện tại đơn — sai vì cần lùi thì sau said)', 'had been', 'has been', 'was (quá khứ đơn — sai vì cần past perfect cho since)'], 1, 'Reported speech: lùi present perfect → past perfect (had been).', ['Sai — is (hiện tại đơn) không lùi thì sau "said".', 'Đúng — reported speech: lùi present perfect continuous → past perfect (had been).', 'Sai — has been không lùi thì sau "said".', 'Sai — was (quá khứ đơn) không hợp; "since" cần dạng hoàn thành (had been).']),
    Q('"The book ___ now belongs to me." (đang được đọc)', ['reading', 'being read', 'read (V3 — chỉ bị động hoàn thành, không phải đang được đọc)', 'to read'], 1, 'Reduced relative clause bị động liên tục: being + V3.', ['Sai — reading (V-ing chủ động) sai; sách "đang được đọc" nên bị động.', 'Đúng — reduced relative clause bị động tiếp diễn: being + V3 (being read).', 'Sai — read (V3) chỉ bị động hoàn thành, không phải đang được đọc.', 'Sai — to read sai dạng; ngữ cảnh là đang được đọc (bị động tiếp diễn).']),
    Q('"She ___ have told him the truth, but she didn\'t."', ['can (có thể — không diễn tả hối tiếc quá khứ)', 'should', 'will (sẽ — tương lai, không hợp ngữ cảnh)', 'must (chắc chắn đã — không phải lời khuyên hối tiếc)'], 1, 'Should have V3 - đáng lẽ phải làm.', ['Sai — can không diễn tả hối tiếc quá khứ.', 'Đúng — should have V3 — đáng lẽ phải làm (nhưng đã không).', 'Sai — will là tương lai, không hợp ngữ cảnh hối tiếc.', 'Sai — must (chắc chắn đã) không phải lời khuyên/hối tiếc.']),
    Q('"Not only ___ English, but he also speaks French."', ['does he speak', 'he is speaking', 'can he speak', 'he speaks'], 0, 'Not only + đảo ngữ + ..., but ... also: does + S + V.', ['Đúng — Not only + đảo ngữ + ..., but... also: does + S + V (does he speak).', 'Sai — he is speaking không đảo ngữ sau "Not only".', 'Sai — can he speak đảo ngữ nhưng thêm modal sai nghĩa câu.', 'Sai — he speaks không đảo trợ động từ ra trước chủ ngữ.']),
    Q('"Hardly ever ___ to the beach."', ['goes I', 'do I go', 'I go (không đảo ngữ sau Hardly ever)', 'I do go'], 1, 'Hardly ever - trạng từ phủ định → đảo ngữ.', ['Sai — goes I sai trật tự đảo ngữ.', 'Đúng — Hardly ever (phủ định) → đảo ngữ: do + S + V (do I go).', 'Sai — I go không đảo ngữ sau "Hardly ever".', 'Sai — I do go không đảo trợ động từ ra trước chủ ngữ.']),
  ]),

  // ──────────────── HK2 ────────────────
  M(19, 'Unit 10 — Lifelong Learning (Gerunds vs infinitives)', [
    Q('"I enjoy ___ books in my free time."', ['reads (hiện tại đơn ngôi thứ ba — sai cấu trúc enjoy)', 'reading', 'read (nguyên thể — sai sau enjoy)', 'to read'], 1, 'Enjoy + V-ing (gerund).', ['Sai — reads (hiện tại đơn ngôi 3) sai cấu trúc sau "enjoy".', 'Đúng — enjoy + V-ing (gerund): reading.', 'Sai — read (nguyên thể) sai sau "enjoy"; cần V-ing.', 'Sai — to read (to-infinitive) sai sau "enjoy"; cần V-ing.']),
    Q('"She decided ___ a foreign language."', ['learn (nguyên thể không to — sai sau decide)', 'to learn', 'learns', 'learning'], 1, 'Decide + to V (infinitive).', ['Sai — learn (nguyên thể không to) sai sau "decide".', 'Đúng — decide + to V (infinitive): to learn.', 'Sai — learns (hiện tại đơn) sai sau "decided".', 'Sai — learning (V-ing) sai sau "decide"; cần to V.']),
    Q('"Lifelong learning" means ___.', ['learning only in school', 'continuous learning throughout life', 'learning quickly', 'learning a specific subject'], 1, 'Lifelong learning - học tập suốt đời.', ['Sai — lifelong learning không chỉ giới hạn trong trường học.', 'Đúng — lifelong learning là học tập liên tục suốt đời.', 'Sai — không nhấn việc học nhanh.', 'Sai — không giới hạn ở một môn cụ thể.']),
    Q('"He stopped ___ when he saw the red light." (mục đích)', ['smoking', 'smoke (nguyên thể không to — sai cấu trúc stop)', 'smoked', 'to smoke'], 3, 'Stop to V - dừng lại để làm gì; stop V-ing - bỏ làm gì.', ['Sai — stop V-ing nghĩa "bỏ làm gì"; ở đây là dừng lại để làm (mục đích).', 'Sai — smoke (nguyên thể không to) sai cấu trúc sau "stop".', 'Sai — smoked (quá khứ) sai dạng sau "stop".', 'Đúng — stop to V = dừng lại để làm gì (mục đích).']),
    Q('"I forgot ___ the door this morning." (việc cần làm nhưng quên)', ['lock (nguyên thể không to — sai cấu trúc forget)', 'to lock', 'locked', 'locking'], 1, 'Forget to V - quên (chưa làm); forget V-ing - quên (đã làm).', ['Sai — lock (nguyên thể không to) sai cấu trúc sau "forget".', 'Đúng — forget to V = quên (chưa làm); ở đây quên khoá cửa.', 'Sai — locked (quá khứ) sai dạng sau "forget".', 'Sai — forget V-ing nghĩa "quên đã làm"; ngữ cảnh là chưa làm.']),
    Q('"It\'s no use ___ over spilt milk."', ['crying', 'to cry', 'cry (nguyên thể — sai sau "It\'s no use")', 'cried (quá khứ đơn — sai sau "It\'s no use")'], 0, 'It\'s no use + V-ing - không ích gì khi làm.', ['Đúng — It\'s no use + V-ing = không ích gì khi làm (crying).', 'Sai — to cry sai dạng sau "It\'s no use"; cần V-ing.', 'Sai — cry (nguyên thể) sai sau "It\'s no use".', 'Sai — cried (quá khứ đơn) sai sau "It\'s no use".']),
  ]),

  M(20, 'Unit 10 — Advanced vocabulary on education', [
    Q('A person who never stops learning is called a ___.', ['illiterate', 'lifelong learner', 'dropout', 'procrastinator'], 1, 'Lifelong learner - người học tập suốt đời.', ['Sai — illiterate nghĩa "mù chữ", trái nghĩa.', 'Đúng — lifelong learner = người học tập suốt đời.', 'Sai — dropout nghĩa "người bỏ học", trái nghĩa.', 'Sai — procrastinator nghĩa "người trì hoãn", nhầm nghĩa.']),
    Q('Synonym of "acquire knowledge" is ___.', ['forget', 'reject', 'lose knowledge', 'gain knowledge'], 3, 'Acquire = gain (đạt được, thu được).', ['Sai — forget (quên) trái nghĩa với thu nhận kiến thức.', 'Sai — reject (từ chối) trái nghĩa.', 'Sai — lose knowledge (mất kiến thức) trái nghĩa.', 'Đúng — acquire = gain (đạt được, thu được).']),
    Q('"MOOC" stands for ___.', ['Mass Open Offline Course', 'My Online Open Class', 'Multiple Online Optional Course', 'Massive Open Online Course'], 3, 'MOOC - khoá học mở trực tuyến đại trà (Coursera, edX…).', ['Sai — sai cụm; MOOC không phải "Mass Open Offline Course".', 'Sai — không phải "My Online Open Class".', 'Sai — không phải "Multiple Online Optional Course".', 'Đúng — MOOC = Massive Open Online Course (khoá học mở trực tuyến đại trà).']),
    Q('"To brush up on" something means to ___.', ['start fresh', 'review and improve', 'ignore', 'forget'], 1, 'Brush up on - ôn lại, cải thiện kĩ năng cũ.', ['Sai — start fresh nghĩa bắt đầu lại từ đầu, không phải ôn lại.', 'Đúng — brush up on = ôn lại, cải thiện kĩ năng cũ.', 'Sai — ignore (phớt lờ) trái nghĩa.', 'Sai — forget (quên) trái nghĩa.']),
    Q('"Self-study" means studying ___.', ['online only', 'with a teacher', 'on your own', 'in a group'], 2, 'Self-study - tự học (không có giáo viên trực tiếp).', ['Sai — self-study không nhất thiết chỉ trực tuyến.', 'Sai — self-study là không có giáo viên trực tiếp, không phải "with a teacher".', 'Đúng — self-study = tự học (on your own).', 'Sai — self-study là học một mình, không phải học nhóm.']),
    Q('"He has a thirst ___ knowledge."', ['of (giới từ — HS nhầm với "thirst of" trong tiếng mẹ đẻ)', 'for', 'to (giới từ chỉ hướng — không hợp collocation)', 'about (giới từ chỉ chủ đề — không hợp với thirst)'], 1, 'A thirst FOR knowledge - khao khát kiến thức (collocation).', ['Sai — "of" sai collocation; có thể do dịch sát tiếng mẹ đẻ "khát của".', 'Đúng — a thirst FOR knowledge — khao khát kiến thức (collocation).', 'Sai — "to" chỉ hướng, không hợp collocation với thirst.', 'Sai — "about" chỉ chủ đề, không hợp với thirst.']),
  ]),

  M(21, 'Tenses comprehensive review', [
    Q('"By next year, I ___ here for ten years."', ['will be working', 'will have been working', 'will work', 'will have worked'], 1, 'Will have been V-ing + for + duration: future perfect continuous (đặc biệt với động từ chỉ trạng thái + duration → cũng có thể dùng future perfect).', ['Sai — will be working (tương lai tiếp diễn) không diễn tả khoảng kéo dài tới mốc tương lai với "for".', 'Đúng — will have been V-ing + for + duration (future perfect continuous).', 'Sai — will work (tương lai đơn) không khớp "for ten years" tới mốc tương lai.', 'Sai — will have worked đúng dạng hoàn thành nhưng phương án continuous nhấn quá trình kéo dài chuẩn hơn.']),
    Q('"While she ___ TV, the phone rang."', ['watches', 'was watching', 'had watched', 'watched'], 1, 'Past continuous (was V-ing) + when/while + past simple.', ['Sai — watches (hiện tại đơn) không khớp ngữ cảnh quá khứ "rang".', 'Đúng — past continuous (was watching) + when/while + past simple.', 'Sai — had watched (quá khứ hoàn thành) chỉ việc đã xong trước, không phải đang diễn ra.', 'Sai — watched (quá khứ đơn) không diễn tả việc đang diễn ra thì bị chen ngang.']),
    Q('"I ___ him since we were children."', ['know (hiện tại đơn — sai vì có since)', 'have known', 'am knowing', 'knew (quá khứ đơn — sai vì có since)'], 1, 'Since + duration → present perfect; "know" là động từ trạng thái → không dùng tiếp diễn.', ['Sai — know (hiện tại đơn) không khớp "since".', 'Đúng — since + duration → present perfect (have known); "know" là động từ trạng thái không dùng tiếp diễn.', 'Sai — am knowing sai; "know" là động từ trạng thái, không dùng tiếp diễn.', 'Sai — knew (quá khứ đơn) không khớp "since" chỉ khoảng kéo dài tới hiện tại.']),
    Q('"They ___ for an hour before the bus arrived."', ['were waiting', 'had been waiting', 'waited', 'have been waiting'], 1, 'Past perfect continuous (had been V-ing) cho hành động kéo dài trước một mốc quá khứ.', ['Sai — were waiting (quá khứ tiếp diễn) không nhấn khoảng kéo dài trước mốc quá khứ với "for an hour before".', 'Đúng — past perfect continuous (had been waiting) cho hành động kéo dài trước một mốc quá khứ.', 'Sai — waited (quá khứ đơn) không nhấn tính kéo dài trước "the bus arrived".', 'Sai — have been waiting (hiện tại hoàn thành tiếp diễn) sai vì ngữ cảnh quá khứ.']),
    Q('"Look at those clouds! It ___ rain."', ['will (dự đoán không có bằng chứng — sai)', 'is going to', 'is raining', 'rains (hiện tại đơn — không phù hợp dự đoán)'], 1, 'Be going to - dự đoán dựa trên bằng chứng hiện tại (mây đen).', ['Sai — will là dự đoán không có bằng chứng; ở đây có bằng chứng (mây đen).', 'Đúng — be going to — dự đoán dựa trên bằng chứng hiện tại (mây đen).', 'Sai — is raining (hiện tại tiếp diễn) chỉ việc đang xảy ra, không phải dự đoán.', 'Sai — rains (hiện tại đơn) không phù hợp để dự đoán.']),
    Q('"The train ___ at 7:30 every morning."', ['is leaving', 'leaves', 'left (quá khứ đơn — sai vì "every morning")', 'will leave'], 1, 'Lịch trình cố định → present simple.', ['Sai — is leaving (hiện tại tiếp diễn) không dùng cho lịch trình lặp lại "every morning".', 'Đúng — lịch trình cố định → present simple (leaves).', 'Sai — left (quá khứ đơn) sai vì "every morning" chỉ thói quen/lịch trình.', 'Sai — will leave (tương lai) không dùng cho lịch trình cố định lặp lại.']),
  ]),

  M(22, 'Passive voice — all tenses review', [
    Q('"The bridge ___ next year." (sẽ được xây)', ['will be built', 'was built', 'is built', 'will build'], 0, 'Future simple passive: will + be + V3.', ['Đúng — future simple passive: will + be + V3 (will be built).', 'Sai — was built (quá khứ bị động) không khớp "next year".', 'Sai — is built (hiện tại bị động) không khớp mốc tương lai.', 'Sai — will build là chủ động; ngữ cảnh cần bị động (được xây).']),
    Q('"My car ___ at the moment." (đang được sửa)', ['is repairing', 'repaired', 'is being repaired', 'has repaired'], 2, 'Present continuous passive: am/is/are + being + V3.', ['Sai — is repairing là chủ động; xe "đang được sửa" nên bị động.', 'Sai — repaired đứng một mình thiếu trợ động từ bị động (is being).', 'Đúng — present continuous passive: am/is/are + being + V3 (is being repaired).', 'Sai — has repaired là chủ động hoàn thành, không khớp "at the moment".']),
    Q('"The letter ___ by my friend last week."', ['was written', 'was being written', 'wrote (chủ động — sai vì câu là bị động)', 'has been written'], 0, 'Past simple passive: was/were + V3.', ['Đúng — past simple passive: was/were + V3 (was written).', 'Sai — was being written (quá khứ tiếp diễn bị động) nhấn việc đang diễn ra, không hợp "last week".', 'Sai — wrote là chủ động; câu này bị động (lá thư được viết).', 'Sai — has been written (hiện tại hoàn thành bị động) không khớp "last week".']),
    Q('"This song ___ by millions of people." (đã được nghe)', ['has been heard', 'has heard', 'heard (chủ động quá khứ — sai vì câu là bị động)', 'is hearing'], 0, 'Present perfect passive: has/have + been + V3.', ['Đúng — present perfect passive: has/have + been + V3 (has been heard).', 'Sai — has heard là chủ động; bài hát là đối tượng được nghe.', 'Sai — heard (chủ động quá khứ) sai vì câu là bị động.', 'Sai — is hearing là chủ động tiếp diễn, sai cả thể lẫn động từ trạng thái.']),
    Q('"People believe that he is innocent." → He ___ to be innocent.', ['believed', 'was believed', 'is believed', 'believes'], 2, 'Mẫu "People believe that S V" → "S is believed to V".', ['Sai — believed thiếu trợ động từ bị động (is); không tạo thành bị động.', 'Sai — was believed sai về thời (gốc "is innocent" ở hiện tại).', 'Đúng — mẫu "People believe that S V" → "S is believed to V".', 'Sai — believes là chủ động, ngữ cảnh cần bị động.']),
    Q('"This work ___ by tomorrow." (sẽ đã được hoàn thành)', ['will be finishing', 'will have been finished', 'was finished', 'will finish'], 1, 'Future perfect passive: will have been + V3.', ['Sai — will be finishing là chủ động tiếp diễn; ngữ cảnh cần bị động hoàn thành.', 'Đúng — future perfect passive: will have been + V3 (will have been finished).', 'Sai — was finished (quá khứ bị động) không khớp "by tomorrow".', 'Sai — will finish là chủ động, không nhấn sự hoàn tất trước mốc.']),
  ]),

  M(23, 'Reported speech — questions + commands', [
    Q('"What time does the meeting start?" → He asked me what time ___.', ['the meeting started', 'the meeting starts', 'does the meeting start', 'did the meeting start'], 0, 'Reported question (Wh): trật tự khẳng định + lùi thì.', ['Đúng — reported question (Wh): trật tự khẳng định + lùi thì (the meeting started).', 'Sai — the meeting starts không lùi thì sau "asked".', 'Sai — does the meeting start giữ trợ động từ nghi vấn, sai trong câu tường thuật.', 'Sai — did the meeting start giữ trật tự nghi vấn, sai trong tường thuật.']),
    Q('"Will you come to my party?" → She asked me if I ___ to her party.', ['came (quá khứ đơn — HS nhầm lùi thì nhưng sai dạng)', 'come (nguyên thể — không lùi thì sau asked)', 'would come', 'will come'], 2, 'Yes/no question reported: if + lùi will → would.', ['Sai — came (quá khứ đơn) sai dạng; lùi will phải thành would.', 'Sai — come (nguyên thể) không lùi thì sau "asked".', 'Đúng — yes/no question reported: if + lùi will → would (would come).', 'Sai — will come không lùi thì sau "asked".']),
    Q('"Please don\'t be late," he said. → He asked us ___ late.', ['to be not', 'don\'t be', 'to not be', 'not to be'], 3, 'Mệnh lệnh phủ định reported: asked sb NOT TO + V.', ['Sai — to be not sai trật tự; "not" phải đứng trước "to".', 'Sai — don\'t be giữ dạng mệnh lệnh trực tiếp, không phải tường thuật.', 'Sai — to not be sai trật tự; phải "not to be".', 'Đúng — mệnh lệnh phủ định reported: asked sb NOT TO + V (not to be).']),
    Q('"Let\'s go for a walk," she said. → She suggested ___ for a walk.', ['that we go', 'to go (HS nhầm cấu trúc suggest + to V)', 'both B and C', 'going (chỉ V-ing, bỏ qua phương án that we go)'], 2, 'Suggest + V-ing hoặc Suggest that S (should) V.', ['Sai — "that we go" đúng nhưng đáp án còn bao gồm "going" nên phải chọn "both".', 'Sai — suggest không đi với to V (suggest + V-ing hoặc that S V).', 'Đúng — suggest + V-ing hoặc suggest that S (should) V — cả hai dạng đúng.', 'Sai — "going" đúng nhưng bỏ sót phương án "that we go" hợp lệ.']),
    Q('"Did you finish your homework?" → He asked me if I ___ my homework.', ['was finishing', 'finished', 'have finished', 'had finished'], 3, 'Past simple → past perfect khi reported.', ['Sai — was finishing (quá khứ tiếp diễn) không hợp; past simple lùi thành past perfect.', 'Sai — finished (quá khứ đơn) chưa lùi đủ; phải thành past perfect.', 'Sai — have finished không lùi thì sau "asked".', 'Đúng — past simple → past perfect khi reported (had finished).']),
    Q('"Don\'t touch this!" the teacher shouted. → The teacher told us ___.', ['don\'t touch this', 'not to touch that', 'to not touch that', 'not to touch this'], 1, 'Negative imperative reported: not to V + đổi "this" → "that".', ['Sai — don\'t touch this giữ dạng trực tiếp và không đổi "this" → "that".', 'Đúng — negative imperative reported: not to V + đổi "this" → "that".', 'Sai — to not touch sai trật tự; phải "not to touch".', 'Sai — đúng cấu trúc nhưng chưa đổi "this" → "that" theo quy tắc tường thuật.']),
  ]),

  M(24, 'Conditionals — all types review', [
    Q('"If you ___ ice, it ___."', ['heat/will melt', 'heat/melts', 'heated/would melt', 'will heat/melts'], 1, 'Type 0 (chân lí khoa học): If + present, ... + present.', ['Sai — type 0 không dùng "will" ở mệnh đề chính; cả hai vế đều present.', 'Đúng — type 0 (chân lí khoa học): If + present, ... + present (heat/melts).', 'Sai — heated/would melt thuộc loại 2 (giả định), không phải chân lí.', 'Sai — không dùng "will" ở mệnh đề if.']),
    Q('"If it rains tomorrow, we ___ the picnic."', ['would cancel', 'will cancel', 'would have cancelled', 'cancel'], 1, 'Type 1: If + present, ... will + V.', ['Sai — would cancel thuộc loại 2, không hợp với "if it rains".', 'Đúng — type 1: If + present, ... will + V (will cancel).', 'Sai — would have cancelled thuộc loại 3, không hợp với "if it rains".', 'Sai — cancel (hiện tại đơn) thiếu "will" ở mệnh đề chính.']),
    Q('"If I ___ a millionaire, I would travel the world."', ['am (hiện tại đơn — sai vì cần if loại 2)', 'will be', 'were', 'was (HS nhầm dùng was cho I trong if loại 2)'], 2, 'Type 2: If + were (thay was sau I/he/she).', ['Sai — am (hiện tại đơn) sai trong if loại 2.', 'Sai — will be thuộc loại 1, không hợp với "would travel".', 'Đúng — type 2: If + were (thay was) — were a millionaire.', 'Sai — was bị nhầm cho "I"; loại 2 quy ước dùng "were".']),
    Q('"If she ___ harder, she would have passed."', ['had studied', 'studies', 'has studied', 'studied'], 0, 'Type 3: If + had V3, ... would have V3.', ['Đúng — type 3: If + had V3 (had studied), ... would have V3.', 'Sai — studies (hiện tại đơn) sai trong if loại 3.', 'Sai — has studied (hiện tại hoàn thành) sai trong if loại 3; cần had V3.', 'Sai — studied (quá khứ đơn) thuộc loại 2, không hợp "would have passed".']),
    Q('"If you had told me earlier, I ___ here now."', ['will be', 'am (hiện tại đơn — sai cấu trúc điều kiện hỗn hợp)', 'would be', 'would have been'], 2, 'Mixed: If + had V3 (past), ... would V (present).', ['Sai — will be thuộc loại 1, không hợp với "if you had told".', 'Sai — am (hiện tại đơn) sai cấu trúc điều kiện hỗn hợp.', 'Đúng — mixed: If + had V3 (past), ... would V (present) — "now".', 'Sai — would have been chỉ kết quả quá khứ; ở đây "now" cần kết quả hiện tại.']),
    Q('"Were I ___, I would invest in this company." (đảo ngữ type 2)', ['rich is', 'being rich', 'to be rich', 'rich'], 3, 'Đảo ngữ type 2: Were + S + adj/N: nếu là.', ['Sai — rich is sai trật tự đảo ngữ; cần Were + S + adj.', 'Sai — being rich sai dạng sau "Were".', 'Sai — to be rich sai dạng trong đảo ngữ loại 2.', 'Đúng — đảo ngữ type 2: Were + S + adj/N (Were I rich).']),
  ]),

  M(25, 'Modal verbs — present + perfect form', [
    Q('"You ___ smoke here. It\'s prohibited."', ['shouldn\'t', 'needn\'t', 'mustn\'t', 'don\'t have to'], 2, 'Mustn\'t - cấm tuyệt đối.', ['Sai — shouldn\'t là lời khuyên không nên, không phải cấm tuyệt đối.', 'Sai — needn\'t nghĩa "không cần", không phải cấm.', 'Đúng — mustn\'t = cấm tuyệt đối (prohibited).', 'Sai — don\'t have to nghĩa "không bắt buộc", không phải cấm.']),
    Q('"You ___ pay; the entrance is free."', ['can\'t (không thể — chỉ khả năng, không phải nghĩa vụ)', 'mustn\'t', 'shouldn\'t', 'don\'t have to'], 3, 'Don\'t have to - không cần (không bắt buộc).', ['Sai — can\'t chỉ khả năng/cấm, không hợp nghĩa "không cần trả tiền".', 'Sai — mustn\'t là cấm, trái với nghĩa "free entrance".', 'Sai — shouldn\'t là lời khuyên không nên, không hợp ngữ cảnh.', 'Đúng — don\'t have to = không cần (không bắt buộc), vì vào cửa miễn phí.']),
    Q('"He ___ have been at home. I saw him at the office."', ['must (chắc chắn đã — trái với bằng chứng nhìn thấy ở văn phòng)', 'should', 'might (có thể đã — quá yếu khi đã có bằng chứng)', 'can\'t'], 3, 'Can\'t have V3 - chắc chắn không (suy đoán phủ định về quá khứ).', ['Sai — must (chắc chắn đã) trái với bằng chứng nhìn thấy ở văn phòng.', 'Sai — should have không hợp ngữ cảnh suy đoán phủ định.', 'Sai — might (có thể đã) quá yếu khi đã có bằng chứng phản bác.', 'Đúng — can\'t have V3 — chắc chắn không (suy đoán phủ định về quá khứ).']),
    Q('"She ___ have left already; her bag is here."', ['must (chắc chắn đã rời đi — trái với bằng chứng túi còn đây)', 'might (có thể đã rời đi — không khớp bằng chứng)', 'should', 'can\'t'], 3, '"Can\'t have left" - không thể đã rời đi (bằng chứng: bag vẫn ở đây).', ['Sai — must (chắc chắn đã rời đi) trái với bằng chứng túi còn đây.', 'Sai — might (có thể đã rời đi) không khớp bằng chứng túi còn đây.', 'Sai — should have không hợp ngữ cảnh suy đoán dựa bằng chứng.', 'Đúng — can\'t have left — không thể đã rời đi (bằng chứng: bag vẫn ở đây).']),
    Q('"They ___ have warned us about the danger!" (hối tiếc)', ['will (sẽ — tương lai, không phải hối tiếc)', 'can (có thể — chỉ khả năng, không phải hối tiếc)', 'should', 'must (chắc chắn đã — không phải hối tiếc/trách móc)'], 2, 'Should have V3 - đáng lẽ phải làm (trách móc).', ['Sai — will là tương lai, không diễn tả hối tiếc.', 'Sai — can chỉ khả năng, không phải hối tiếc.', 'Đúng — should have V3 — đáng lẽ phải làm (trách móc).', 'Sai — must (chắc chắn đã) không phải hối tiếc/trách móc.']),
    Q('"He ___ have missed the train; he\'s usually punctual."', ['should', 'can\'t', 'might (có thể đã lỡ — không khớp với "usually punctual")', 'must (chắc chắn đã lỡ — trái với "usually punctual")'], 1, '"Can\'t have missed" - khó tin rằng anh ấy đã lỡ tàu.', ['Sai — should have không hợp ngữ cảnh suy đoán phủ định.', 'Đúng — can\'t have missed — khó tin anh ấy đã lỡ tàu (vì usually punctual).', 'Sai — might (có thể đã lỡ) không khớp với "usually punctual".', 'Sai — must (chắc chắn đã lỡ) trái với "usually punctual".']),
  ]),

  M(26, 'Inversion + Cleft sentences review', [
    Q('"Rarely ___ such a delicious meal."', ['I have had', 'have I had', 'I had (không đảo ngữ sau Rarely)', 'did I have'], 1, 'Rarely + auxiliary + S + V (đảo ngữ).', ['Sai — I have had không đảo trợ động từ ra trước chủ ngữ sau "Rarely".', 'Đúng — Rarely + auxiliary + S + V (have I had) — đảo ngữ.', 'Sai — I had không đảo ngữ sau "Rarely".', 'Sai — did I have sai thì; ngữ cảnh kinh nghiệm dùng have + V3.']),
    Q('"Only when he apologised ___ him."', ['I forgave', 'did I forgive', 'I had forgiven', 'do I forgive'], 1, 'Only + adverbial → đảo ngữ ở mệnh đề chính.', ['Sai — I forgave không đảo trợ động từ ra trước chủ ngữ.', 'Đúng — Only + adverbial → đảo ngữ ở mệnh đề chính (did I forgive).', 'Sai — I had forgiven không đảo ngữ sau "Only when".', 'Sai — do I forgive sai thì; ngữ cảnh quá khứ (apologised).']),
    Q('"It was at the party ___ I met her."', ['when (chỉ thời gian — sai vì at the party là nơi chốn)', 'where (trạng ngữ nơi chốn — không dùng trong It-cleft chuẩn)', 'which (đại từ quan hệ — không hợp cleft)', 'that'], 3, 'It-cleft: it was + adverbial + that + clause.', ['Sai — when chỉ thời gian; "at the party" là nơi chốn.', 'Sai — where không dùng trong It-cleft chuẩn.', 'Sai — which là đại từ quan hệ, không hợp cleft với trạng ngữ.', 'Đúng — It-cleft: It was + adverbial + that + clause (that).']),
    Q('"What I need is ___."', ['to some rest', 'having rest', 'some rest', 'some rest is'], 2, 'What-cleft: What + clause + is + thing emphasised.', ['Sai — to some rest thừa "to"; what-cleft nhấn trực tiếp danh từ.', 'Sai — having rest sai dạng; cần danh từ được nhấn mạnh.', 'Đúng — what-cleft: What + clause + is + thing emphasised (some rest).', 'Sai — some rest is thừa "is"; "is" đã có trong cấu trúc cleft.']),
    Q('"___ such a problem!" (Never have I seen)', ['Never had I seen', 'Never have I seen', 'Never seen I have', 'Never I have seen'], 1, 'Never + have + S + V3 (đảo ngữ).', ['Sai — Never had I seen sai thì; ngữ cảnh kinh nghiệm dùng have + V3.', 'Đúng — Never + have + S + V3 (have I seen) — đảo ngữ.', 'Sai — Never seen I have sai trật tự đảo ngữ.', 'Sai — Never I have seen không đảo trợ động từ ra trước chủ ngữ.']),
    Q('"Little ___ that he was lying."', ['I had known', 'do I know', 'I knew', 'did I know'], 3, 'Little (= không hề) + đảo ngữ trợ động từ.', ['Sai — I had known không đảo trợ động từ ra trước chủ ngữ.', 'Sai — do I know sai thì; ngữ cảnh quá khứ "he was lying".', 'Sai — I knew không đảo ngữ sau "Little".', 'Đúng — Little (= không hề) + đảo ngữ trợ động từ (did I know).']),
  ]),

  M(27, 'Relative clauses + reduced clauses review', [
    Q('"The man ___ car was stolen called the police."', ['whom (tân ngữ chỉ người — không thay sở hữu được)', 'that (đại từ quan hệ — không thay sở hữu cách)', 'who (chủ ngữ chỉ người — không phải sở hữu)', 'whose'], 3, 'Whose - sở hữu (his car = whose car).', ['Sai — whom là tân ngữ chỉ người, không thay sở hữu.', 'Sai — that không thay được sở hữu cách.', 'Sai — who làm chủ ngữ chỉ người, không diễn tả sở hữu.', 'Đúng — whose = sở hữu (his car = whose car).']),
    Q('"The students ___ in the front row are the best."', ['sitting', 'to sit', 'sits (hiện tại đơn — sai trong cấu trúc rút gọn)', 'sat (quá khứ đơn — sai trong cấu trúc rút gọn chủ động)'], 0, 'Rút gọn "who are sitting" → sitting (V-ing chủ động).', ['Đúng — rút gọn "who are sitting" → sitting (V-ing chủ động).', 'Sai — to sit sai dạng rút gọn chủ động ở đây.', 'Sai — sits (hiện tại đơn) sai trong cấu trúc rút gọn.', 'Sai — sat (quá khứ đơn) sai trong rút gọn chủ động.']),
    Q('"The bridge ___ in 1990 collapsed last week."', ['was built', 'built', 'to build', 'building'], 1, 'Rút gọn "which was built" → built (V3 bị động).', ['Sai — was built đầy đủ mệnh đề, không phải dạng rút gọn.', 'Đúng — rút gọn "which was built" → built (V3 bị động).', 'Sai — to build sai dạng rút gọn ở đây.', 'Sai — building (V-ing chủ động) sai; cây cầu được xây nên bị động.']),
    Q('"This is the village ___ I grew up."', ['where', 'which (đại từ quan hệ vật — không chỉ nơi chốn)', 'who (dùng cho người — village không phải người)', 'that (đại từ quan hệ — không thay where trực tiếp)'], 0, 'Where = in which - chỉ nơi chốn.', ['Đúng — where = in which — chỉ nơi chốn (the village).', 'Sai — which chỉ vật, không chỉ nơi chốn ở đây.', 'Sai — who dùng cho người; village không phải người.', 'Sai — that không thay được "where" trực tiếp ở vị trí này.']),
    Q('"London, ___ is the capital of England, is a beautiful city."', ['who (dùng cho người — London là thành phố)', 'where (trạng ngữ nơi chốn — sai vì là chủ ngữ)', 'which', 'that (không dùng trong non-defining có dấu phẩy)'], 2, 'Non-defining clause cho vật → which (không dùng that, có dấu phẩy).', ['Sai — who dùng cho người; London là thành phố.', 'Sai — where là trạng ngữ nơi chốn, sai vì làm chủ ngữ.', 'Đúng — non-defining clause cho vật → which (có dấu phẩy).', 'Sai — that không dùng trong mệnh đề non-defining có dấu phẩy.']),
    Q('"The reason ___ I came is to see you."', ['that (đại từ quan hệ — không thay cho "for which")', 'where (trạng ngữ nơi chốn — sai vì là lý do)', 'why', 'which (đại từ quan hệ — không thay why trực tiếp)'], 2, 'Why = for which - chỉ lí do.', ['Sai — that không thay được "for which" sau "the reason".', 'Sai — where chỉ nơi chốn, sai vì đây là lí do.', 'Đúng — why = for which — chỉ lí do (the reason why).', 'Sai — which không thay "why" trực tiếp sau "the reason".']),
  ]),

  M(28, 'Articles (a/an/the/∅) practice', [
    Q('"___ Eiffel Tower is in Paris."', ['An (mạo từ trước nguyên âm — sai với danh từ riêng)', 'The', 'A (mạo từ trước phụ âm — sai với danh từ riêng)', '∅ (no article — sai vì tháp nổi tiếng cần the)'], 1, 'The - dùng cho danh từ riêng địa danh nổi tiếng (tháp, sông, biển…).', ['Sai — An sai với danh từ riêng địa danh.', 'Đúng — the dùng cho danh từ riêng địa danh nổi tiếng (tháp, sông, biển…).', 'Sai — A sai với danh từ riêng địa danh.', 'Sai — bỏ trống sai; tháp nổi tiếng cần "the".']),
    Q('"I had ___ apple and ___ banana for breakfast."', ['a/an (HS đảo thứ tự nguyên âm/phụ âm)', 'a/a (chỉ a — sai với apple nguyên âm)', 'an/a', 'an/an (chỉ an — sai với banana phụ âm)'], 2, 'An + apple (nguyên âm), a + banana (phụ âm).', ['Sai — đảo thứ tự; apple (nguyên âm) cần "an", banana (phụ âm) cần "a".', 'Sai — "a/a" sai với apple (nguyên âm cần "an").', 'Đúng — an + apple (nguyên âm), a + banana (phụ âm).', 'Sai — "an/an" sai với banana (phụ âm cần "a").']),
    Q('"___ Mount Everest is the highest mountain."', ['The (mạo từ xác định — HS nhầm với danh từ địa lý có the)', 'A (mạo từ trước phụ âm — sai với danh từ riêng)', '∅', 'An (mạo từ trước nguyên âm — sai với danh từ riêng)'], 2, 'Tên núi đơn lẻ không dùng "the".', ['Sai — "The" sai; tên núi đơn lẻ không dùng "the".', 'Sai — A sai với danh từ riêng (tên núi).', 'Đúng — tên núi đơn lẻ không dùng "the".', 'Sai — An sai với danh từ riêng (tên núi).']),
    Q('"She plays ___ piano very well."', ['an (mạo từ trước nguyên âm — piano bắt đầu phụ âm)', '∅ (no article — sai vì nhạc cụ cần the)', 'the', 'a (mạo từ không xác định — sai với nhạc cụ chơi)'], 2, 'The + nhạc cụ (the piano, the guitar).', ['Sai — an sai vì piano bắt đầu bằng phụ âm và nhạc cụ cần "the".', 'Sai — bỏ trống sai; tên nhạc cụ chơi cần "the".', 'Đúng — the + nhạc cụ (the piano, the guitar).', 'Sai — a sai với nhạc cụ chơi; cần "the".']),
    Q('"He went to ___ school by bus." (đi học)', ['an (mạo từ trước nguyên âm — sai vì school là phụ âm)', 'the (mạo từ xác định — sai vì go to school chỉ mục đích)', 'a (mạo từ không xác định — sai vì go to school không mạo từ)', '∅'], 3, '"Go to school" - chỉ mục đích học → không mạo từ.', ['Sai — an sai vì school bắt đầu bằng phụ âm.', 'Sai — the sai; "go to school" chỉ mục đích học, không mạo từ.', 'Sai — a sai; "go to school" không dùng mạo từ.', 'Đúng — "go to school" chỉ mục đích học → không mạo từ.']),
    Q('"___ rich should help ___ poor." (giai cấp)', ['An/an (mạo từ trước nguyên âm — sai cấu trúc "the + adj")', 'The/the', '∅/∅ (no article — sai cấu trúc "the + adj")', 'A/a (mạo từ trước phụ âm — sai cấu trúc "the + adj")'], 1, 'The + adj = nhóm người (the rich, the poor, the elderly).', ['Sai — An/an sai cấu trúc "the + adj" chỉ nhóm người.', 'Đúng — the + adj = nhóm người (the rich, the poor).', 'Sai — bỏ trống sai cấu trúc "the + adj".', 'Sai — A/a sai cấu trúc "the + adj" chỉ nhóm người.']),
  ]),

  M(29, 'Phrasal verbs comprehensive', [
    Q('"I came ___ an interesting article in the newspaper."', ['up (come up — xuất hiện/nảy sinh, không phải gặp tình cờ)', 'across', 'off (come off — rơi ra, không hợp ngữ cảnh)', 'about (come about — xảy ra, không phải gặp tình cờ)'], 1, 'Come across - tình cờ gặp/thấy.', ['Sai — come up nghĩa xuất hiện/nảy sinh, không phải gặp tình cờ.', 'Đúng — come across = tình cờ gặp/thấy.', 'Sai — come off nghĩa rơi ra, không hợp ngữ cảnh.', 'Sai — come about nghĩa xảy ra, không phải gặp tình cờ.']),
    Q('"The meeting was ___ due to bad weather."', ['called off', 'called on', 'called for', 'called up'], 0, 'Call off - huỷ bỏ.', ['Đúng — call off = huỷ bỏ.', 'Sai — call on nghĩa ghé thăm/kêu gọi, nhầm nghĩa.', 'Sai — call for nghĩa đòi hỏi/yêu cầu, nhầm nghĩa.', 'Sai — call up nghĩa gọi điện/triệu tập, nhầm nghĩa.']),
    Q('"Please ___ smoking; it\'s bad for your health."', ['give back', 'give away', 'give up', 'give in'], 2, 'Give up - từ bỏ (thói quen).', ['Sai — give back nghĩa trả lại, nhầm nghĩa.', 'Sai — give away nghĩa cho đi/tiết lộ, nhầm nghĩa.', 'Đúng — give up = từ bỏ (thói quen).', 'Sai — give in nghĩa nhượng bộ/đầu hàng, nhầm nghĩa.']),
    Q('"We need to ___ our weak points."', ['work in', 'work on', 'work out', 'work at'], 1, 'Work on - cải thiện, làm việc với.', ['Sai — "work in" không phải phrasal verb chuẩn cho "cải thiện".', 'Đúng — work on = cải thiện, tập trung làm việc với.', 'Sai — work out nghĩa giải quyết/tập thể dục, nhầm nghĩa.', 'Sai — "work at" gần nghĩa nhưng "work on" là collocation chuẩn với "weak points".']),
    Q('"He always ___ his promises."', ['keeps to', 'keeps up with', 'keeps on', 'keeps in'], 0, 'Keep to - giữ (lời hứa, kế hoạch).', ['Đúng — keep to = giữ (lời hứa, kế hoạch).', 'Sai — keep up with nghĩa theo kịp, nhầm nghĩa.', 'Sai — keep on nghĩa tiếp tục, nhầm nghĩa.', 'Sai — "keep in" không hợp collocation với "promises".']),
    Q('"Please ___ the radio; I can\'t hear."', ['turn off', 'turn down', 'turn on', 'turn up'], 3, 'Turn up - tăng âm lượng; turn on - bật; turn down - giảm.', ['Sai — turn off nghĩa tắt, trái với "tăng để nghe rõ".', 'Sai — turn down nghĩa giảm âm lượng, trái nghĩa.', 'Sai — turn on nghĩa bật, không phải tăng âm lượng.', 'Đúng — turn up = tăng âm lượng (để nghe rõ).']),
  ]),

  M(30, 'Vocabulary in context — reading practice', [
    Q('"The festival ___ tourists from all over the world."', ['attacks', 'attracts', 'contracts', 'retracts'], 1, 'Attract - thu hút (collocation: attract tourists/attention).', ['Sai — attacks (tấn công) nhầm nghĩa, không phải thu hút.', 'Đúng — attract = thu hút (collocation: attract tourists).', 'Sai — contracts (ký hợp đồng/co lại) nhầm nghĩa.', 'Sai — retracts (rút lại) nhầm nghĩa.']),
    Q('"Her speech had a strong ___ on the audience."', ['infect', 'defect', 'effect', 'affect'], 2, 'Effect (n) - tác động; affect (v) - tác động đến.', ['Sai — infect (lây nhiễm) nhầm nghĩa.', 'Sai — defect (khuyết tật/đào tẩu) nhầm nghĩa.', 'Đúng — effect (n) = tác động; "had a strong effect on".', 'Sai — affect là động từ; ở đây cần danh từ sau "a strong".']),
    Q('"Vietnam has a rich ___ heritage."', ['culture', 'cultural', 'culturally', 'culturalism'], 1, 'Cultural (adj) - văn hoá, bổ nghĩa cho "heritage".', ['Sai — culture là danh từ, không bổ nghĩa được cho "heritage".', 'Đúng — cultural (adj) bổ nghĩa cho "heritage".', 'Sai — culturally là trạng từ, không bổ nghĩa cho danh từ.', 'Sai — culturalism là danh từ, không phải tính từ bổ nghĩa.']),
    Q('"The new policy will benefit ___ farmers."', ['low-incomes', 'low-income', 'low-incoming', 'low-incomed'], 1, 'Tính từ ghép "low-income" - thu nhập thấp.', ['Sai — low-incomes sai; tính từ ghép không thêm "s".', 'Đúng — tính từ ghép "low-income" — thu nhập thấp.', 'Sai — low-incoming sai dạng; không có dạng này.', 'Sai — low-incomed sai dạng; không có dạng này.']),
    Q('"He gave a ___ description of the event."', ['detailed', 'detail', 'details', 'detailing'], 0, 'Detailed (adj) - chi tiết, bổ nghĩa cho description.', ['Đúng — detailed (adj) bổ nghĩa cho "description".', 'Sai — detail là danh từ, không bổ nghĩa cho "description".', 'Sai — details là danh từ số nhiều, không phải tính từ.', 'Sai — detailing (V-ing) không hợp làm tính từ bổ nghĩa ở đây.']),
    Q('"We need to take ___ action to solve this problem."', ['immediately', 'immediating', 'immediate', 'immediacy'], 2, 'Immediate (adj) - ngay lập tức, bổ nghĩa cho "action".', ['Sai — immediately là trạng từ, không bổ nghĩa cho danh từ "action".', 'Sai — immediating không tồn tại.', 'Đúng — immediate (adj) bổ nghĩa cho "action".', 'Sai — immediacy là danh từ, không phải tính từ.']),
  ]),

  M(31, 'Writing — common mistakes', [
    Q('Choose the correct sentence:', ['I look forward to hearing from you.', 'I look forward to hear from you.', 'I look forward hear from you.', 'I look forward hearing from you.'], 0, 'Look forward TO + V-ing (to là giới từ).', ['Đúng — look forward TO + V-ing (to là giới từ): hearing.', 'Sai — to hear sai; "to" là giới từ nên cần V-ing (hearing).', 'Sai — thiếu "to" và sai dạng động từ.', 'Sai — thiếu "to" giữa forward và hearing.']),
    Q('"In spite of ___ tired, he kept working."', ['was (HS thiếu chủ ngữ — In spite of không nhận mệnh đề)', 'he was', 'he is (mệnh đề hoàn chỉnh — sai vì In spite of + N/V-ing)', 'being'], 3, 'In spite of + N/V-ing (không phải mệnh đề).', ['Sai — was thiếu chủ ngữ; "In spite of" không nhận mệnh đề.', 'Sai — he was tạo mệnh đề; "In spite of" + N/V-ing.', 'Sai — he is tạo mệnh đề hoàn chỉnh; "In spite of" cần N/V-ing.', 'Đúng — In spite of + N/V-ing (being tired).']),
    Q('"Although ___, he kept working."', ['tired (tính từ đơn — sai vì Although cần mệnh đề)', 'being tired', 'he was tired', 'he tired'], 2, 'Although + clause (S + V).', ['Sai — tired (tính từ đơn) sai; "Although" cần mệnh đề.', 'Sai — being tired là cụm V-ing; "Although" cần mệnh đề S + V.', 'Đúng — Although + clause (he was tired).', 'Sai — he tired thiếu động từ "to be"; phải "he was tired".']),
    Q('Choose correct: "She is good ___ math."', ['on (giới từ vị trí — HS nhầm với "on math")', 'in (giới từ chỉ chuyên ngành — HS nhầm với "good in")', 'for (giới từ chỉ mục đích — không hợp collocation)', 'at'], 3, 'Good AT + skill/subject (collocation).', ['Sai — "on" sai collocation; có thể nhầm với "on math".', 'Sai — "in" nhầm với cụm "good in" sai chuẩn.', 'Sai — "for" chỉ mục đích, không hợp collocation "good at".', 'Đúng — good AT + skill/subject (collocation).']),
    Q('"He is interested ___ history."', ['at (interested at — HS nhầm với good at)', 'for (interested for — không phải collocation chuẩn)', 'on (interested on — không phải collocation chuẩn)', 'in'], 3, 'Interested IN + topic.', ['Sai — "at" nhầm với "good at"; "interested" đi với "in".', 'Sai — "for" không phải collocation chuẩn với interested.', 'Sai — "on" không phải collocation chuẩn với interested.', 'Đúng — interested IN + topic.']),
    Q('"___ his hard work, he failed the exam."', ['Despite', 'Because of', 'Although', 'Because'], 0, 'Despite + N/V-ing - mặc dù; "his hard work" là danh từ.', ['Đúng — Despite + N/V-ing — mặc dù; "his hard work" là danh từ.', 'Sai — Because of chỉ nguyên nhân, mâu thuẫn với kết quả "failed".', 'Sai — Although + mệnh đề, không đi với cụm danh từ "his hard work".', 'Sai — Because + mệnh đề và chỉ nguyên nhân, không hợp ngữ cảnh.']),
  ]),

  M(32, 'Listening + Speaking exam practice', [
    Q('Listening tips: To catch keywords, focus on ___.', ['every word', 'intonation only', 'content words (nouns, verbs, adj)', 'function words (a, the)'], 2, 'Tập trung content words mang nghĩa - bỏ qua mạo từ/giới từ nhẹ.', ['Sai — không cần nghe từng từ; tập trung từ mang nghĩa.', 'Sai — chỉ ngữ điệu là chưa đủ để bắt từ khoá.', 'Đúng — content words (danh từ, động từ, tính từ) mang nghĩa cần tập trung.', 'Sai — function words (a, the) mang ít nghĩa, không phải từ khoá.']),
    Q('In multiple-choice listening, you should ___ before listening.', ['hurry to answer (vội trả lời — không phải chiến lược tốt)', 'read all questions/options', 'take notes only', 'close eyes'], 1, 'Đọc trước câu hỏi và đáp án giúp định hướng nghe.', ['Sai — vội trả lời không phải chiến lược tốt.', 'Đúng — đọc trước câu hỏi và đáp án giúp định hướng nghe.', 'Sai — chỉ ghi chú là chưa đủ; cần đọc trước câu hỏi.', 'Sai — nhắm mắt không phải chiến lược nghe hiệu quả.']),
    Q('When you don\'t understand a word, you should ___.', ['give up', 'keep listening for context', 'stop listening', 'translate every word (dịch từng từ — làm chậm và mất context)'], 1, 'Tiếp tục nghe để bắt context - đừng dừng lại vì 1 từ.', ['Sai — không nên bỏ cuộc vì một từ.', 'Đúng — tiếp tục nghe để bắt context, đừng dừng vì 1 từ.', 'Sai — dừng nghe khiến bỏ lỡ thông tin sau đó.', 'Sai — dịch từng từ làm chậm và mất context.']),
    Q('Speaking: to develop your answer, use ___.', ['single words', 'reasons + examples + extensions', 'only "yes/no"', 'silence'], 1, 'Trả lời mở rộng: lí do + ví dụ + liên hệ - tránh "yes/no".', ['Sai — trả lời bằng từ đơn không phát triển được câu.', 'Đúng — lí do + ví dụ + liên hệ giúp phát triển câu trả lời.', 'Sai — chỉ "yes/no" không mở rộng được câu.', 'Sai — im lặng không phải cách phát triển câu trả lời.']),
    Q('Pronunciation: word stress in "DEVelopment" falls on ___.', ['1st syllable', '2nd syllable', '3rd syllable', '4th syllable'], 1, 'Trọng âm rơi vào âm tiết thứ 2: de-VE-lop-ment.', ['Sai — trọng âm không rơi vào âm tiết thứ 1.', 'Đúng — trọng âm rơi vào âm tiết thứ 2: de-VE-lop-ment.', 'Sai — không phải âm tiết thứ 3.', 'Sai — không phải âm tiết thứ 4.']),
    Q('To sound natural, use ___ correctly.', ['linking words and intonation', 'one tone only', 'only formal vocabulary', 'only past tense'], 0, 'Linking words (firstly, however, therefore…) + intonation phù hợp.', ['Đúng — linking words + intonation phù hợp giúp nói tự nhiên.', 'Sai — một tông duy nhất nghe đơn điệu, kém tự nhiên.', 'Sai — chỉ từ vựng trang trọng không giúp nói tự nhiên.', 'Sai — chỉ thì quá khứ không liên quan đến độ tự nhiên.']),
  ]),

  M(33, 'Reading comprehension strategies', [
    Q('Skimming means reading ___.', ['every word', 'quickly to get the main idea', 'only the conclusion', 'for specific details'], 1, 'Skimming - đọc nhanh để nắm ý chính.', ['Sai — skimming không phải đọc từng từ.', 'Đúng — skimming = đọc nhanh để nắm ý chính.', 'Sai — skimming không chỉ đọc kết luận.', 'Sai — đọc tìm chi tiết cụ thể là scanning, không phải skimming.']),
    Q('Scanning means reading ___.', ['for specific information/details', 'word by word', 'quickly for main idea', 'every word'], 0, 'Scanning - tìm thông tin cụ thể (con số, tên riêng…).', ['Đúng — scanning = tìm thông tin cụ thể (con số, tên riêng…).', 'Sai — đọc từng từ trái với scanning.', 'Sai — đọc nhanh tìm ý chính là skimming, không phải scanning.', 'Sai — scanning không phải đọc từng từ.']),
    Q('When you see "in contrast", expect ___.', ['difference', 'example', 'conclusion', 'similarity'], 0, 'In contrast - dấu hiệu chuyển sang ý đối lập.', ['Đúng — "in contrast" báo hiệu ý đối lập (difference).', 'Sai — "in contrast" không dẫn vào ví dụ.', 'Sai — "in contrast" không phải dấu hiệu kết luận.', 'Sai — "in contrast" báo đối lập, không phải tương đồng.']),
    Q('"Inference" means ___.', ['reading between the lines', 'summarising', 'stated directly', 'copying'], 0, 'Inference - suy luận, hiểu ý ngầm từ văn bản.', ['Đúng — inference = suy luận, hiểu ý ngầm (reading between the lines).', 'Sai — tóm tắt khác với suy luận ý ngầm.', 'Sai — nêu trực tiếp trái với inference (ý ngầm).', 'Sai — sao chép không phải suy luận.']),
    Q('For vocabulary in context, look at ___.', ['title (chỉ tiêu đề — không đủ để đoán từ cụ thể)', 'dictionary only', 'image (hình ảnh — không phải mọi bài đọc đều có)', 'surrounding sentences'], 3, 'Đoán nghĩa từ - dựa vào ngữ cảnh các câu xung quanh.', ['Sai — chỉ tiêu đề không đủ để đoán nghĩa từ cụ thể.', 'Sai — chỉ từ điển không phải đoán nghĩa trong ngữ cảnh.', 'Sai — hình ảnh không phải lúc nào cũng có trong bài đọc.', 'Đúng — đoán nghĩa từ dựa vào ngữ cảnh các câu xung quanh.']),
    Q('"Topic sentence" usually appears ___.', ['at the end', 'at the beginning of a paragraph', 'as a title', 'in the middle'], 1, 'Topic sentence (câu chủ đề) thường ở đầu đoạn (paragraph).', ['Sai — topic sentence không thường ở cuối đoạn.', 'Đúng — topic sentence (câu chủ đề) thường ở đầu đoạn.', 'Sai — topic sentence không phải tiêu đề.', 'Sai — topic sentence ít khi nằm giữa đoạn.']),
  ]),

  M(34, 'Final review — practice test 1', [
    Q('"Had I known about the traffic, I ___ earlier."', ['will have left', 'left (quá khứ đơn — sai vì đảo ngữ cần would have V3)', 'would have left', 'would leave'], 2, 'Đảo ngữ type 3: Had + S + V3, ... would have V3.', ['Sai — will have left không hợp với đảo ngữ điều kiện loại 3.', 'Sai — left (quá khứ đơn) sai; đảo ngữ loại 3 cần would have V3.', 'Đúng — đảo ngữ type 3: Had + S + V3, ... would have V3 (would have left).', 'Sai — would leave thuộc loại 2, không hợp "Had I known".']),
    Q('"By the time she arrives, we ___ dinner."', ['finish', 'will finish', 'finished', 'will have finished'], 3, '"By the time" + present (arrives) → future perfect.', ['Sai — finish (hiện tại đơn) không khớp ngữ cảnh hoàn tất trước mốc.', 'Sai — will finish không nhấn sự hoàn tất trước "by the time she arrives".', 'Sai — finished (quá khứ) không hợp với mốc tương lai.', 'Đúng — "by the time" + present (arrives) → future perfect (will have finished).']),
    Q('"It was not until 1945 ___ Vietnam ___ independent."', ['that/became', 'that/became', 'when/became', 'when/become'], 0, 'Not until + time + that + S V (cleft, không đảo ngữ trong dạng này).', ['Đúng — Not until + time + that + S V (cleft): that/became.', 'Sai — đúng "that/became" nhưng đây là phương án trùng; chọn đáp án đầu.', 'Sai — cleft chuẩn dùng "that", không dùng "when".', 'Sai — "when/become" sai cả từ nối lẫn dạng động từ.']),
    Q('"___ studying English for 5 years, she can speak fluently."', ['To have', 'Had (đảo ngữ điều kiện — không hợp cấu trúc rút gọn lý do)', 'Having', 'Having been'], 2, 'Having V3 + ... - mệnh đề trạng ngữ rút gọn (since/because).', ['Sai — To have sai dạng; rút gọn lí do dùng Having V3.', 'Sai — Had (đảo ngữ điều kiện) không hợp cấu trúc rút gọn lí do.', 'Đúng — Having V3 + ... — mệnh đề trạng ngữ rút gọn (since/because).', 'Sai — Having been + V3 dùng cho bị động; ở đây là chủ động (studying).']),
    Q('"Neither ___ nor ___ are responsible." (cấu trúc song hành)', ['he/I', 'him/I (him là tân ngữ — sai vì cần chủ ngữ)', 'he/me (me là tân ngữ — sai vì cần chủ ngữ)', 'him/me'], 0, 'Neither X nor Y + are - cùng dạng chủ ngữ; "he" và "I" cùng là subject.', ['Đúng — Neither X nor Y cùng làm chủ ngữ; "he" và "I" cùng dạng subject.', 'Sai — "him" là tân ngữ; vị trí này cần chủ ngữ.', 'Sai — "me" là tân ngữ; vị trí này cần chủ ngữ.', 'Sai — "him/me" đều là tân ngữ; cần chủ ngữ (he/I).']),
    Q('"The book ___ I bought yesterday is very interesting."', ['that', 'where (trạng ngữ nơi chốn — sai vì là tân ngữ chỉ vật)', 'whose (sở hữu cách — sai vì là tân ngữ trực tiếp)', 'who (dùng cho người — sai vì book là vật)'], 0, 'That/which - đại từ quan hệ cho vật.', ['Đúng — that/which — đại từ quan hệ làm tân ngữ cho vật (book).', 'Sai — where là trạng ngữ nơi chốn; ở đây là tân ngữ chỉ vật.', 'Sai — whose là sở hữu cách; ở đây là tân ngữ trực tiếp.', 'Sai — who dùng cho người; book là vật.']),
  ]),

  M(35, 'Final review — practice test 2 + exam strategies', [
    Q('"If only I ___ harder in school!" (regret about past)', ['have studied', 'had studied', 'studied', 'study (hiện tại đơn — sai vì If only cần had V3 cho hối tiếc)'], 1, 'If only + had V3 - tiếc nuối về quá khứ.', ['Sai — have studied (hiện tại hoàn thành) không hợp; If only hối tiếc quá khứ cần had V3.', 'Đúng — If only + had V3 — tiếc nuối về quá khứ.', 'Sai — studied (quá khứ đơn) chưa đủ; hối tiếc quá khứ cần had V3.', 'Sai — study (hiện tại đơn) sai; If only cần had V3 cho hối tiếc.']),
    Q('"He suggested ___ a meeting next week."', ['to hold', 'hold (nguyên thể — sai vì suggest + V-ing)', 'to holding', 'holding'], 3, 'Suggest + V-ing (gerund).', ['Sai — suggest không đi với to V.', 'Sai — hold (nguyên thể) sai; suggest + V-ing.', 'Sai — to holding sai dạng kép.', 'Đúng — suggest + V-ing (gerund): holding.']),
    Q('"The teacher made us ___ the test again."', ['take', 'to take', 'taken (V3 — sai vì make sb + V nguyên thể chủ động)', 'taking'], 0, 'Make sb + V (nguyên thể không "to").', ['Đúng — make sb + V (nguyên thể không "to"): take.', 'Sai — to take sai; "make sb" + V nguyên thể không "to".', 'Sai — taken (V3) sai; cấu trúc chủ động cần nguyên thể.', 'Sai — taking (V-ing) sai sau "make sb".']),
    Q('"I would rather you ___ smoke here."', ['wouldn\'t', 'didn\'t', 'don\'t (hiện tại đơn — sai vì would rather cần past simple)', 'won\'t (will not — sai vì would rather cần past simple)'], 1, 'Would rather + S + V-ed (past simple) cho hiện tại/tương lai.', ['Sai — wouldn\'t sai; "would rather + S" dùng past simple (didn\'t).', 'Đúng — would rather + S + V-ed (past simple) cho hiện tại/tương lai (didn\'t).', 'Sai — don\'t (hiện tại đơn) sai; would rather + S cần past simple.', 'Sai — won\'t sai; would rather + S cần past simple (didn\'t).']),
    Q('"It\'s high time we ___ home."', ['went', 'go (hiện tại đơn — sai vì It\'s high time cần V-ed)', 'will go', 'have gone'], 0, 'It\'s high time + S + V-ed - đã đến lúc làm gì rồi.', ['Đúng — It\'s high time + S + V-ed (went) — đã đến lúc làm gì.', 'Sai — go (hiện tại đơn) sai; It\'s high time cần V-ed.', 'Sai — will go sai; It\'s high time cần past simple.', 'Sai — have gone sai; It\'s high time cần past simple (went).']),
    Q('Exam tip: When you finish, you should ___.', ['check answers carefully', 'submit immediately', 'leave early', 'rush to leave (vội rời đi — bỏ qua bước kiểm tra)'], 0, 'Dành 5-10 phút cuối kiểm tra - lỗi chính tả, đáp án bỏ sót.', ['Đúng — dành 5-10 phút cuối kiểm tra lỗi chính tả, đáp án bỏ sót.', 'Sai — nộp ngay bỏ qua bước kiểm tra lại.', 'Sai — rời sớm không phải chiến lược tốt khi thi.', 'Sai — vội rời đi bỏ qua bước kiểm tra bài.']),
  ]),
  M(36, 'Closing Chapter — Your English Journey Continues', [
    Q('Why is reading in English described as essential for university study?', ['Because exams only test reading', 'Because it replaces listening practice', 'Because it gives access to academic texts, research papers and news', 'Because it is the easiest skill'], 2, 'Reading gives access to academic texts, research papers and news, which university study depends on.', ['No — the exam tests several skills, not reading alone.', 'No — listening remains a separate skill to practise.', 'Correct — academic texts and research are largely published in English.', 'No — difficulty varies from learner to learner.']),
    Q('Which discourse markers are recommended for the writing task?', ['However, furthermore, in conclusion', 'Um, well, you know', 'Yeah, ok, sure', 'Hi, bye, thanks'], 0, 'Discourse markers such as however, furthermore and in conclusion structure an essay clearly.', ['Correct — these markers signal contrast, addition and conclusion in formal writing.', 'No — those are spoken fillers, not written markers.', 'No — those are informal conversational responses.', 'No — those are greetings, not discourse markers.']),
    Q('How long should you spend planning your essay before writing, according to the exam tips?', ['No planning at all', 'About 2 minutes', 'About 20 minutes', 'Half of the exam time'], 1, 'The tips suggest planning the essay in about two minutes before writing.', ['No — a short plan prevents a disorganised essay.', 'Correct — about two minutes of planning is enough to structure the essay.', 'No — 20 minutes of planning leaves too little time to write.', 'No — planning should be brief.']),
    Q('What time-management strategy is suggested for the graduation exam?', ['Answer the questions strictly in order, no matter how hard', 'Spend all the time on the writing task', 'Leave difficult questions blank from the start', 'Complete easier questions first, then flag and return to difficult ones'], 3, 'Complete easier questions first, then flag the difficult ones and return to them.', ['No — a hard question early can consume the whole exam.', 'No — the multiple-choice section carries most of the marks.', 'No — you should return to difficult questions rather than abandon them.', 'Correct — secure the easy marks first, then return to the difficult items.']),
    Q('For vocabulary and grammar questions, what technique is recommended?', ['Answer from what you know and eliminate obvious wrong choices', 'Guess without reading the options', 'Always choose the longest option', 'Always choose option A'], 0, 'Answer from what you know and eliminate clearly wrong options.', ['Correct — elimination raises the chance of a correct answer.', 'No — reading the options is part of the elimination process.', 'No — option length carries no information about correctness.', 'No — a fixed choice is not a strategy.']),
    Q('Which of these is named as a door that English opens after graduation?', ['Only domestic work with no travel', 'English-medium university programs and international exchange', 'Only manual labour jobs', 'Only jobs that require no communication'], 1, 'English opens English-medium university programs, exchange opportunities and research in English.', ['No — English widens rather than narrows opportunities.', 'Correct — English-medium programs and exchanges are named directly in the lesson.', 'No — the lesson points to global professional opportunities.', 'No — English is valued precisely for communication.']),
  ]),
];

export const H12TA_SCENARIOS = indexBy(H12TA_WEEKS);
